export const templates={"admin":"<body\n  @open-profile.window=\"goTo('profile')\"\n  class=\"app-shell bg-material-bg text-material-text flex overflow-hidden font-sans antialiased\"\n  style=\"height: 100dvh\"\n  x-data=\"admin\"\n  @keydown.escape.window=\"closePanels()\"\n>\n  <aside\n    :class=\"drawer ? 'translate-x-0' : '-translate-x-full md:translate-x-0'\"\n    class=\"app-sidebar fixed md:relative inset-y-0 left-0 z-40 w-64 bg-white flex flex-col shrink-0 shadow-soft transition-transform -translate-x-full md:translate-x-0\"\n    style=\"height: 100dvh\"\n    aria-label=\"Menú principal\"\n  >\n    <div class=\"p-6 border-b border-material-border\">\n      <p class=\"font-bold text-material-dark tracking-wider\">PORTONSMART</p>\n      <p class=\"text-xs mt-2\">Administración del edificio</p>\n    </div>\n    <nav class=\"flex-1 min-h-0 overflow-y-auto p-4\">\n      <div\n        x-data=\"buildingPicker\"\n        x-show=\"linked && options.length > 1\"\n        class=\"px-3 py-3 mb-3 bg-white text-material-dark border border-gray-200\"\n      >\n        <label x-show=\"linked && options.length > 1\" class=\"block text-xs\"\n          >Edificio que controlas<select\n            x-ref=\"buildingSelect\"\n            x-model=\"selected\"\n            @change=\"change()\"\n            class=\"w-full mt-2 border p-2 text-sm\"\n          >\n            <template x-for=\"o in options\" :key=\"o.url\"\n              ><option :value=\"o.url\" x-text=\"o.label\"></option\n            ></template></select\n        ></label>\n      </div>\n      <a\n        href=\"#inicio\"\n        @click.prevent=\"goTo('inicio')\"\n        :aria-current=\"tab === 'inicio' ? 'page' : null\"\n        :class=\"tab === 'inicio' ? 'bg-material-dark text-white' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center gap-3 px-3 py-3 text-sm font-medium\"\n        ><i class=\"fa-solid fa-house w-5\" aria-hidden=\"true\"></i>Inicio</a\n      >\n      <a\n        href=\"#accesos\"\n        @click.prevent=\"goTo('accesos')\"\n        :aria-current=\"tab === 'accesos' ? 'page' : null\"\n        :class=\"tab === 'accesos' ? 'bg-material-dark text-white' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center gap-3 px-3 py-3 text-sm font-medium\"\n        ><i class=\"fa-solid fa-door-open w-5\" aria-hidden=\"true\"></i>Portones</a\n      >\n      <a\n        href=\"#residentes\"\n        @click.prevent=\"goTo('residentes')\"\n        :aria-current=\"tab === 'residentes' ? 'page' : null\"\n        :class=\"tab === 'residentes' ? 'bg-material-dark text-white' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center gap-3 px-3 py-3 text-sm font-medium\"\n        ><i class=\"fa-solid fa-users w-5\" aria-hidden=\"true\"></i>Residentes</a\n      >\n      <a\n        href=\"#pases\"\n        @click.prevent=\"goTo('pases')\"\n        :aria-current=\"tab === 'pases' ? 'page' : null\"\n        :class=\"tab === 'pases' ? 'bg-material-dark text-white' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center gap-3 px-3 py-3 text-sm font-medium\"\n        ><i class=\"fa-solid fa-key w-5\" aria-hidden=\"true\"></i>Códigos</a\n      >\n      <a\n        href=\"#actividad\"\n        @click.prevent=\"goTo('actividad')\"\n        :aria-current=\"tab === 'actividad' ? 'page' : null\"\n        :class=\"tab === 'actividad' ? 'bg-material-dark text-white' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center gap-3 px-3 py-3 text-sm font-medium\"\n        ><i class=\"fa-solid fa-clock-rotate-left w-5\" aria-hidden=\"true\"></i\n        >Historial</a\n      ><a\n        href=\"#configuracion\"\n        @click.prevent=\"openSettings()\"\n        :class=\"tab === 'configuracion' ? 'bg-material-dark text-white' : 'text-material-dark'\"\n        class=\"flex gap-3 items-center px-3 py-3 text-sm\"\n        ><i class=\"fa-solid fa-gear w-5\" aria-hidden=\"true\"></i>Configuración</a\n      >\n    </nav>\n    <a\n      href=\"?section=profile\"\n      @click.prevent=\"goTo('profile')\"\n      aria-label=\"Mi perfil\"\n      class=\"p-4 border-t text-sm flex items-center gap-3 hover:bg-gray-50\"\n      ><span\n        class=\"w-9 h-9 bg-material-dark text-white flex items-center justify-center shrink-0\"\n        x-text=\"initials\"\n      ></span\n      ><span class=\"min-w-0 flex-1\"\n        ><span\n          class=\"block font-semibold truncate\"\n          x-text=\"user.username\"\n        ></span\n        ><span class=\"text-xs\">Administración</span></span\n      ><i class=\"fa-solid fa-chevron-right text-xs\" aria-hidden=\"true\"></i\n    ></a>\n    <div class=\"sidebar-session\">\n  <button type=\"button\" @click=\"logout()\" class=\"sidebar-logout\">\n    <i class=\"fa-solid fa-right-from-bracket\" aria-hidden=\"true\"></i\n    ><span>Cerrar sesión</span>\n  </button>\n</div>\n\n  </aside>\n  <div\n    x-show=\"drawer\"\n    x-cloak\n    @click=\"drawer = false\"\n    class=\"fixed inset-0 bg-black/30 z-30 md:hidden\"\n  ></div>\n  <div\n    x-show=\"error\"\n    x-cloak\n    role=\"alert\"\n    class=\"fixed top-4 left-1/2 -translate-x-1/2 z-[80] bg-red-50 border border-red-200 text-red-800 p-4 shadow-floating max-w-[90vw]\"\n  >\n    <span x-text=\"error\"></span\n    ><button @click=\"error = ''\" class=\"ml-4 underline\">Cerrar</button>\n  </div>\n  <main\n    id=\"main-scroll\"\n    class=\"flex-1 min-w-0 h-full overflow-y-auto scrollbar-thin\"\n  >\n    <header\n      class=\"px-4 md:px-8 py-4 sticky top-0 bg-material-bg/95 z-20 flex justify-between items-center gap-3\"\n    >\n      <div class=\"min-w-0\">\n        <p class=\"text-xs truncate\" x-text=\"tenant.name\"></p>\n        <h1 class=\"font-bold text-material-dark text-lg md:text-xl\">\n          Panel de administración\n        </h1>\n      </div>\n      <button\n        @click=\"drawer = true\"\n        class=\"md:hidden bg-white shadow-soft w-11 h-11 shrink-0\"\n        aria-label=\"Abrir menú\"\n      >\n        <i class=\"fa-solid fa-bars\"></i>\n      </button>\n    </header>\n    <div class=\"px-4 md:px-8 pb-10 max-w-7xl mx-auto\">\n      <div class=\"flex justify-end mb-3\">\n        <button\n          @click=\"refresh()\"\n          :disabled=\"busy\"\n          class=\"text-xs underline py-2\"\n        >\n          Actualizar datos\n        </button>\n      </div>\n      <section\n        x-show=\"page === 'inicio'\"\n        x-cloak\n        data-panel-page=\"inicio\"\n        id=\"inicio\"\n      >\n        <div class=\"flex justify-between items-center mb-3\">\n          <h2 class=\"text-lg font-bold\">Resumen</h2>\n        </div>\n        <p x-show=\"loading\" role=\"status\">Cargando datos…</p>\n        <div class=\"grid grid-cols-2 md:grid-cols-3 gap-3\">\n          <div class=\"bg-white shadow-soft p-4\">\n            <p class=\"text-xs\">Órdenes enviadas hoy</p>\n            <p class=\"text-2xl font-bold mt-1\" x-text=\"summary.today || 0\"></p>\n          </div>\n          <button\n            @click=\"goTo('pases')\"\n            class=\"bg-white shadow-soft p-4 text-left\"\n          >\n            <p class=\"text-xs\">Códigos activos</p>\n            <p\n              class=\"text-2xl font-bold mt-1\"\n              x-text=\"summary.activeCodes || 0\"\n            ></p></button\n          ><button\n            @click=\"goTo('residentes')\"\n            class=\"bg-white shadow-soft p-4 text-left\"\n          >\n            <p class=\"text-xs\">Residentes</p>\n            <p class=\"text-2xl font-bold mt-1\" x-text=\"residentCount\"></p>\n          </button>\n        </div>\n        <div class=\"mt-3 space-y-2\">\n          <template x-for=\"a in alerts\" :key=\"a.id\"\n            ><div class=\"bg-amber-50 border border-amber-200 p-3 text-sm\">\n              <strong x-text=\"a.title\"></strong>\n              <p x-text=\"a.body\"></p>\n              <div class=\"flex gap-4 mt-2\">\n                <button @click=\"focusDevice(a.device)\" class=\"underline\">\n                  Ver historial</button\n                ><button @click=\"dismiss(a.id)\" class=\"underline\">\n                  Ocultar aviso\n                </button>\n              </div>\n            </div></template\n          >\n          <p class=\"text-xs\">\n            Los estados corresponden a la última consulta; no son monitoreo\n            continuo.\n          </p>\n        </div>\n      </section>\n      <div class=\"mt-6\">\n        <section\n          x-show=\"page === 'accesos'\"\n          x-cloak\n          data-panel-page=\"accesos\"\n          id=\"accesos\"\n          aria-labelledby=\"t-abrir\"\n        >\n          <h2 id=\"t-abrir\" class=\"text-lg font-bold text-material-dark mb-3\">\n            Portones\n          </h2>\n          <p\n            x-show=\"!loading && doors.length === 0\"\n            class=\"bg-white p-5 mb-6 text-sm\"\n          >\n            No hay portones habilitados. Contacta al superadministrador.\n          </p>\n          <div\n            class=\"grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3 md:gap-4\"\n          >\n            <template x-for=\"d in doors\" :key=\"d.id\">\n              <article class=\"relative bg-white shadow-soft\">\n                <div\n                  class=\"absolute top-3 right-3 w-9 h-9 bg-material-dark flex items-center justify-center text-white\"\n                >\n                  <svg\n                    viewBox=\"0 0 24 24\"\n                    class=\"w-5 h-5\"\n                    :class=\"d.state === 'abierto' ? 'gate-open' : ''\"\n                    fill=\"none\"\n                    stroke=\"currentColor\"\n                    stroke-width=\"1.8\"\n                    aria-hidden=\"true\"\n                  >\n                    <path d=\"M2 21V3h20v18\" />\n                    <path class=\"gate-left\" d=\"M4 6h8v14H4zM8 6v14\" />\n                    <path class=\"gate-right\" d=\"M12 6h8v14h-8zM16 6v14\" />\n                  </svg>\n                </div>\n                <div class=\"p-3 pr-14 pb-2\">\n                  <h3\n                    class=\"text-base font-bold text-material-dark leading-snug\"\n                    x-text=\"d.name\"\n                  ></h3>\n                  <p class=\"mt-1 text-xs flex items-center gap-1.5\">\n                    <span\n                      class=\"w-1.5 h-1.5 rounded-full\"\n                      :class=\"d.online ? 'bg-emerald-500' : 'bg-red-500'\"\n                    ></span>\n                    <span x-text=\"statusLine(d)\"></span>\n                  </p>\n                </div>\n                <div class=\"px-3 pb-2\">\n                  <button\n                    type=\"button\"\n                    class=\"hold relative w-full h-[52px] overflow-hidden border font-bold text-sm transition-colors\"\n                    :class=\"btnClass(d)\"\n                    :disabled=\"!d.online || d.state === 'abriendo' || d.state === 'abierto'\"\n                    :aria-label=\"'Abrir ' + d.name + '. ' + label(d)\"\n                    @pointerdown.prevent=\"startHold(d.id)\"\n                    @pointerup=\"cancelHold(d.id)\"\n                    @pointerleave=\"cancelHold(d.id)\"\n                    @pointercancel=\"cancelHold(d.id)\"\n                    @blur=\"cancelHold(d.id)\"\n                    @contextmenu.prevent\n                    @keydown.enter.prevent=\"startHold(d.id)\"\n                    @keydown.space.prevent=\"startHold(d.id)\"\n                    @keyup.enter=\"cancelHold(d.id)\"\n                    @keyup.space=\"cancelHold(d.id)\"\n                  >\n                    <!-- Relleno: avanza como un portón que se desliza -->\n                    <span\n                      class=\"absolute inset-y-0 left-0\"\n                      :class=\"fillClass(d)\"\n                      :style=\"'width:' + (d.progress) + '%; transition: ' + (d.state === 'sosteniendo' ? 'none' : 'width .25s ease')\"\n                    ></span>\n                    <!-- Texto oscuro (parte aún sin llenar) -->\n                    <span\n                      class=\"absolute inset-0 flex items-center justify-center gap-2 px-4\"\n                      :class=\"textClass(d)\"\n                      :style=\"'clip-path: inset(0 0 0 ' + (d.progress) + '%)'\"\n                    >\n                      <i :class=\"icon(d)\" aria-hidden=\"true\"></i\n                      ><span x-text=\"label(d)\"></span>\n                    </span>\n                    <!-- Texto claro (parte ya llena) -->\n                    <span\n                      class=\"absolute inset-0 flex items-center justify-center gap-2 px-4 text-white pointer-events-none\"\n                      aria-hidden=\"true\"\n                      :style=\"'clip-path: inset(0 ' + (100 - d.progress) + '% 0 0)'\"\n                    >\n                      <i :class=\"icon(d)\"></i><span x-text=\"label(d)\"></span>\n                    </span>\n                  </button>\n                  <button\n                    @click=\"confirmDoor(d)\"\n                    :disabled=\"d.state === 'abriendo'\"\n                    class=\"mt-1 w-full min-h-[40px] py-2 text-xs underline text-material-text\"\n                  >\n                    Abrir con confirmación\n                  </button>\n                  <p\n                    x-show=\"d.hint\"\n                    x-cloak\n                    class=\"mt-2 text-xs text-amber-700\"\n                  >\n                    Sigue presionando hasta que la barra se llene.\n                  </p>\n                </div>\n                <div class=\"border-t border-material-border p-3 text-xs\">\n                  <p>Última consulta: <span x-text=\"checkedText(d)\"></span></p>\n                  <div class=\"flex flex-wrap gap-3 mt-2\">\n                    <button\n                      x-show=\"d.hasRelay\"\n                      @click=\"check(d)\"\n                      :disabled=\"checking || busy\"\n                      class=\"underline min-h-[36px]\"\n                      x-text=\"checking === d.id ? 'Consultando…' : 'Comprobar conexión'\"\n                    ></button\n                    ><button\n                      @click=\"focusDevice(d.id)\"\n                      class=\"underline min-h-[36px]\"\n                    >\n                      Ver historial\n                    </button>\n                  </div>\n                  <details x-show=\"d.hasRelay\" class=\"mt-2\">\n                    <summary class=\"cursor-pointer py-2 font-semibold\">\n                      Detalles de conexión\n                    </summary>\n                    <p class=\"break-all\" x-text=\"d.deviceId\"></p>\n                    <p class=\"mt-2\">\n                      Señal Wi-Fi:\n                      <span\n                        x-text=\"d.rssi === null ? 'Sin medición' : d.rssi + ' dBm'\"\n                      ></span>\n                    </p>\n                    <p>\n                      Tiempo encendido en la última consulta:\n                      <span x-text=\"d.uptime\"></span>\n                    </p>\n                    <p class=\"mt-2\">Observaciones de las últimas 24 horas</p>\n                    <div class=\"flex gap-1 my-2\">\n                      <template x-for=\"(c,i) in d.cells\" :key=\"i\"\n                        ><span\n                          class=\"h-3 flex-1\"\n                          :class=\"cellClass(c)\"\n                          :title=\"'Hace ' + (23-i) + ' h: ' + (c === 'ok' ? 'Conectado' : c === 'down' ? 'Desconectado' : 'Sin observación')\"\n                        ></span\n                      ></template>\n                    </div>\n                    <p>Gris: sin observación. No es monitoreo continuo.</p>\n                  </details>\n                </div>\n              </article>\n            </template>\n          </div>\n          <p class=\"mt-4 text-xs text-material-text\">\n            Mantén presionado el botón para abrir. Así evitas aperturas\n            accidentales desde el bolsillo.\n          </p>\n          <p class=\"sr-only\" aria-live=\"polite\" x-text=\"live\"></p>\n        </section>\n      </div>\n      <details\n        x-show=\"page === 'inicio'\"\n        x-cloak\n        class=\"mt-5 bg-white shadow-soft\"\n      >\n        <summary class=\"p-4 cursor-pointer text-sm font-semibold\">\n          Estadísticas de aperturas\n        </summary>\n        <div\n          class=\"lg:col-span-2 bg-white shadow-soft p-5 md:p-6\"\n          aria-labelledby=\"t-chart\"\n        >\n          <div class=\"flex items-start justify-between gap-4\">\n            <div>\n              <h2 id=\"t-chart\" class=\"text-material-dark font-bold text-base\">\n                Órdenes por hora\n              </h2>\n              <p class=\"text-xs text-gray-500 mt-1\">\n                Hora pico:\n                <span\n                  class=\"font-medium text-material-dark\"\n                  x-text=\"hour(peak) + ' (' + hoy[peak] + ' órdenes)'\"\n                ></span>\n              </p>\n            </div>\n            <div class=\"flex items-center gap-4 text-xs text-gray-500 shrink-0\">\n              <span class=\"flex items-center gap-1.5\"\n                ><span class=\"w-2.5 h-2.5 bg-material-dark\"></span>Hoy</span\n              >\n              <span class=\"flex items-center gap-1.5\"\n                ><span class=\"w-2.5 h-0.5 bg-amber-500\"></span>Ayer</span\n              >\n            </div>\n          </div>\n\n          <div\n            class=\"relative h-52 ml-8 mt-8\"\n            role=\"img\"\n            :aria-label=\"'Aperturas por hora. Hora pico ' + hour(peak)\"\n          >\n            <template x-for=\"g in chartTicks\" :key=\"g\">\n              <div\n                class=\"absolute left-0 right-0 border-t border-material-border\"\n                :style=\"'bottom:' + (g / chartMax * 100) + '%'\"\n              >\n                <span\n                  class=\"absolute -left-8 w-6 text-right text-[11px] text-gray-400 translate-y-1/2\"\n                  x-text=\"g\"\n                ></span>\n              </div>\n            </template>\n            <div class=\"absolute inset-0 flex items-end gap-[3px]\">\n              <template x-for=\"(v, i) in hoy\" :key=\"i\">\n                <div\n                  class=\"flex-1 h-full relative flex items-end\"\n                  tabindex=\"0\"\n                  @mouseenter=\"hover = i\"\n                  @mouseleave=\"hover = null\"\n                  @focus=\"hover = i\"\n                  @blur=\"hover = null\"\n                >\n                  <div\n                    class=\"w-full transition-colors\"\n                    :class=\"(i === peak || hover === i) ? 'bg-material-dark' : 'bg-[#c9d0dc]'\"\n                    :style=\"'height:' + (v / chartMax * 100) + '%'\"\n                  ></div>\n                  <div\n                    class=\"absolute left-0 right-0 h-0.5 bg-amber-500\"\n                    :style=\"'bottom:' + (ayer[i] / chartMax * 100) + '%'\"\n                  ></div>\n                  <div\n                    x-show=\"hover === i\"\n                    x-cloak\n                    class=\"absolute z-10 bottom-full mb-2 left-1/2 -translate-x-1/2 bg-material-darker text-white text-xs px-2.5 py-1.5 whitespace-nowrap shadow-floating pointer-events-none\"\n                  >\n                    <span class=\"font-medium\" x-text=\"hour(i)\"></span> ·\n                    <span x-text=\"v + ' hoy'\"></span> ·\n                    <span\n                      class=\"text-white/70\"\n                      x-text=\"ayer[i] + ' ayer'\"\n                    ></span>\n                  </div>\n                </div>\n              </template>\n            </div>\n          </div>\n          <div class=\"ml-8 mt-2 flex gap-[3px]\" aria-hidden=\"true\">\n            <template x-for=\"(v, i) in hoy\" :key=\"i\">\n              <div\n                class=\"flex-1 flex justify-center text-[11px] text-gray-400 font-mono\"\n              >\n                <span\n                  x-show=\"i % 3 === 0\"\n                  class=\"whitespace-nowrap\"\n                  x-text=\"hourLabel(i)\"\n                ></span>\n              </div>\n            </template>\n          </div>\n        </div>\n      </details>\n      <section\n        x-show=\"page === 'residentes'\"\n        x-cloak\n        data-panel-page=\"residentes\"\n        id=\"residentes\"\n        class=\"bg-white shadow-soft p-4 md:p-6\"\n      >\n        <div class=\"flex flex-wrap items-center justify-between gap-3\">\n          <h2 class=\"text-lg font-bold text-material-dark\">\n            Residentes del edificio\n          </h2>\n          <button\n            @click=\"editUser('create')\"\n            class=\"bg-material-dark text-white px-4 py-3 text-sm\"\n          >\n            Agregar residente\n          </button>\n        </div>\n        <label class=\"block text-sm mt-4\"\n          >Buscar residente<input\n            x-model=\"userQuery\"\n            type=\"search\"\n            class=\"field\"\n            placeholder=\"Nombre o teléfono\"\n        /></label>\n        <label class=\"block text-sm mt-3\"\n          >Filtrar por portón<select class=\"field\" x-model=\"userGate\">\n            <option value=\"\">Todos los portones</option>\n            <template x-for=\"g in doors\" :key=\"g.id\"\n              ><option :value=\"g.id\" x-text=\"g.name\"></option\n            ></template></select\n        ></label>\n        <div class=\"compact-list mt-4\">\n          <template x-for=\"u in filteredUsers\" :key=\"u.id\"\n            ><article class=\"compact-row user-row\">\n  <details>\n    <summary class=\"compact-summary user-summary\">\n      <span\n        class=\"user-avatar\"\n        aria-hidden=\"true\"\n        x-text=\"u.username.slice(0,2).toUpperCase()\"\n      ></span>\n      <span class=\"compact-main\">\n        <h3 class=\"compact-name user-name\" x-text=\"u.username\"></h3>\n        <span class=\"user-gates compact-meta\">\n          <span class=\"gate-label user-role\" x-show=\"u.role === 'master'\"\n            >Administrador</span\n          >\n          <template x-for=\"g in permittedUserGates(u)\" :key=\"g.id\"\n            ><span class=\"gate-label\" x-text=\"g.name\"></span\n          ></template>\n          <span\n            class=\"user-no-gates\"\n            x-show=\"permittedUserGates(u).length === 0\"\n            >Sin accesos asignados</span\n          >\n        </span>\n      </span>\n      <span class=\"user-more\"\n        ><span aria-hidden=\"true\">•••</span\n        ><span class=\"detail-toggle\">Opciones</span></span\n      >\n    </summary>\n    <div class=\"compact-detail\">\n      <p class=\"user-phone\" x-text=\"u.phone || 'Sin teléfono asociado'\"></p>\n      <div class=\"compact-actions\">\n        <button @click=\"showWelcome(u)\" class=\"mini-action\">Compartir</button>\n        <button\n          x-show=\"u.role !== 'master'\"\n          @click=\"editUser('permissions',u)\"\n          class=\"mini-action\"\n        >\n          Accesos permitidos\n        </button>\n        <button\n          x-show=\"u.role !== 'master'\"\n          @click=\"confirmDelete(u)\"\n          class=\"mini-action text-red-700\"\n        >\n          Eliminar\n        </button>\n      </div>\n    </div>\n  </details>\n</article>\n</template\n          >\n        </div>\n        <p x-show=\"filteredUsers.length === 0\" class=\"py-5 text-sm\">\n          No hay residentes con esta búsqueda.\n        </p>\n      </section>\n      <section\n        x-show=\"page === 'pases'\"\n        x-cloak\n        data-panel-page=\"pases\"\n        id=\"pases\"\n        class=\"\"\n        aria-labelledby=\"t-pases\"\n      >\n        <div class=\"relative bg-white shadow-soft\">\n          <div\n            class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\"\n          >\n            <h2 id=\"t-pases\" class=\"text-white font-bold text-base\">\n              Códigos del edificio\n            </h2>\n            <button\n              @click=\"openSheet()\"\n              class=\"on-dark text-xs text-white bg-white/10 hover:bg-white/20 px-3 py-2 font-semibold flex items-center gap-1.5\"\n            >\n              <i class=\"fa-solid fa-plus text-[10px]\" aria-hidden=\"true\"></i>\n              Nuevo código\n            </button>\n          </div>\n\n          <form\n            @submit.prevent=\"loadCodePage()\"\n            class=\"p-4 grid gap-3 md:grid-cols-4\"\n          >\n            <label class=\"text-xs\"\n              >Buscar código o referencia<input\n                x-model=\"codeQuery\"\n                type=\"search\"\n                class=\"field\"\n                placeholder=\"Código, referencia o usuario\" /></label\n            ><label class=\"text-xs\"\n              >Residente<select\n                x-model=\"codeOwner\"\n                @change=\"loadCodePage()\"\n                class=\"field\"\n              >\n                <option value=\"\">Todos</option>\n                <template x-for=\"u in users\" :key=\"u.id\"\n                  ><option :value=\"u.id\" x-text=\"u.username\"></option\n                ></template></select></label\n            ><label class=\"text-xs\"\n              >Portón del código<select\n                x-model=\"codeGate\"\n                @change=\"loadCodePage()\"\n                class=\"field\"\n              >\n                <option value=\"\">Todos los portones</option>\n                <template x-for=\"d in doors\" :key=\"d.id\"\n                  ><option :value=\"d.id\" x-text=\"d.name\"></option\n                ></template></select></label\n            ><label class=\"text-xs\"\n              >Estado del código<select\n                x-model=\"codeStatus\"\n                @change=\"loadCodePage()\"\n                class=\"field\"\n              >\n                <option value=\"current\">Vigentes y en revisión</option>\n                <option value=\"\">Todos</option>\n                <option value=\"active\">Activos</option>\n                <option value=\"expired\">Vencidos</option>\n                <option value=\"revoked\">Revocados</option>\n                <option value=\"used\">Utilizados</option>\n                <option value=\"pending\">En curso</option>\n                <option value=\"uncertain\">Requieren revisión</option>\n              </select></label\n            ><button\n              :disabled=\"codeBusy\"\n              class=\"bg-material-dark text-white px-4 py-2 text-sm\"\n            >\n              Buscar códigos\n            </button>\n          </form>\n          <div class=\"p-4 pt-0\">\n            <p x-show=\"codeBusy\" role=\"status\" class=\"text-sm mb-3\">\n              Consultando códigos…\n            </p>\n            <template x-if=\"listedPasses.length === 0\">\n              <div class=\"py-10 text-center\">\n                <i\n                  class=\"fa-solid fa-qrcode text-2xl text-gray-300\"\n                  aria-hidden=\"true\"\n                ></i>\n                <p class=\"mt-3 text-sm font-medium text-material-dark\">\n                  No hay códigos con estos filtros\n                </p>\n                <p class=\"text-xs text-material-text mt-1\">\n                  Cambia los filtros o crea un código.\n                </p>\n                <button\n                  @click=\"openSheet()\"\n                  class=\"mt-4 text-sm font-semibold text-white bg-material-dark px-4 py-2.5\"\n                >\n                  Crear código\n                </button>\n              </div>\n            </template>\n\n            <div class=\"compact-list\">\n  <template x-for=\"p in displayedPasses\" :key=\"p.id\">\n    <article class=\"compact-row\">\n      <details>\n        <summary class=\"compact-summary\">\n          <span class=\"compact-main\"\n            ><strong\n              class=\"code compact-code\"\n              x-text=\"grouped(p.code)\"\n            ></strong>\n            <h3 class=\"compact-name\" x-text=\"p.name\"></h3>\n            <span class=\"compact-meta\"\n              ><span class=\"gate-label\" x-text=\"accessLabel(p)\"></span\n              ><span x-text=\"p.type\"></span></span\n          ></span>\n          <span class=\"compact-state\"\n            ><span\n              class=\"state-label\"\n              :class=\"p.status === 'uncertain' || p.status === 'pending' ? 'state-warning' : p.status !== 'active' || (p.expiresAt && p.expiresAt <= now) ? 'state-muted' : expiring(p) ? 'state-warning' : 'state-active'\"\n              x-text=\"passStatus(p)\"\n            ></span\n            ><span\n              class=\"compact-expiry\"\n              x-text=\"!p.expiresAt ? 'Sin vencimiento' : p.expiresAt <= now ? 'Vencido' : 'Vence en ' + leftText(p)\"\n            ></span\n            ><span class=\"detail-toggle\"\n              >Ver detalles <span aria-hidden=\"true\">⌄</span></span\n            ></span\n          >\n        </summary>\n        <div class=\"compact-detail\">\n          <p x-text=\"expiryText(p)\"></p>\n          <p x-show=\"showPassOwner\">\n            Creado por <span x-text=\"p.owner\"></span>\n          </p>\n          <div class=\"compact-actions\">\n            <button\n              x-show=\"!p.codeMasked\"\n              @click=\"copy(p)\"\n              class=\"py-2.5 text-xs font-medium text-material-dark hover:bg-gray-50 flex flex-col items-center gap-1\"\n              aria-label=\"Copiar código\"\n            >\n              <i class=\"fa-regular fa-copy\" aria-hidden=\"true\"></i>Copiar\n            </button>\n\n            <button\n              x-show=\"canExtend(p)\"\n              x-cloak\n              @click=\"extend(p)\"\n              class=\"py-2.5 text-xs font-medium text-material-dark hover:bg-gray-50 flex flex-col items-center gap-1\"\n              aria-label=\"Extender 30 minutos\"\n            >\n              <i class=\"fa-solid fa-clock-rotate-left\" aria-hidden=\"true\"></i\n              >+30 min\n            </button>\n            <button\n              x-show=\"canRevoke(p)\"\n              @click=\"confirmRevoke(p)\"\n              class=\"py-2.5 text-xs font-medium flex flex-col items-center gap-1\"\n              :class=\"armed === 'r' + p.id ? 'bg-red-600 text-white' : 'text-red-600 hover:bg-red-50'\"\n            >\n              <i class=\"fa-solid fa-ban\" aria-hidden=\"true\"></i\n              ><span\n                x-text=\"armed === 'r' + p.id ? '¿Seguro?' : 'Revocar'\"\n              ></span>\n            </button>\n          </div>\n        </div>\n      </details>\n      <div class=\"compact-share\" x-show=\"canShare(p)\">\n        <button\n          @click=\"share(p)\"\n          class=\"mini-action\"\n          aria-label=\"Compartir pase\"\n        >\n          Compartir\n        </button>\n      </div>\n    </article>\n  </template>\n</div>\n\n          </div>\n        </div>\n        <div class=\"p-4 text-sm\">\n          <p x-text=\"listedPasses.length + ' códigos mostrados'\"></p>\n          <button\n            x-show=\"codeMore\"\n            :disabled=\"codeBusy\"\n            @click=\"loadCodePage(true)\"\n            class=\"underline py-3\"\n          >\n            Cargar más códigos\n          </button>\n        </div>\n      </section>\n\n      <section\n        x-show=\"page === 'actividad'\"\n        x-cloak\n        data-panel-page=\"actividad\"\n        id=\"actividad\"\n        class=\"\"\n        aria-labelledby=\"t-act\"\n      >\n        <div class=\"relative bg-white shadow-soft\">\n          <div\n            class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\"\n          >\n            <h2 id=\"t-act\" class=\"text-white font-bold text-base\">\n              Historial del edificio\n            </h2>\n          </div>\n          <div class=\"px-5 md:px-6 pt-5 grid gap-3 md:grid-cols-3\">\n            <label class=\"text-xs\"\n              >Buscar en historial<input\n                x-model=\"activityQuery\"\n                type=\"search\"\n                class=\"mt-1 w-full border border-gray-300 p-2\"\n                placeholder=\"Referencia, código o usuario\" /></label\n            ><label class=\"text-xs\"\n              >Filtrar portón<select\n                aria-label=\"Filtrar portón\"\n                x-model=\"activityGate\"\n                class=\"mt-1 w-full border border-gray-300 p-2\"\n              >\n                <option value=\"\">Todos los portones</option>\n                <template x-for=\"d in doors\" :key=\"d.id\"\n                  ><option :value=\"d.id\" x-text=\"d.name\"></option\n                ></template></select></label\n            ><label class=\"text-xs\"\n              >Filtrar resultado<select\n                aria-label=\"Filtrar resultado\"\n                x-model=\"activityResult\"\n                class=\"mt-1 w-full border border-gray-300 p-2\"\n              >\n                <option value=\"\">Todos los resultados</option>\n                <option value=\"sent\">Orden enviada</option>\n                <option value=\"not_sent\">No enviada</option>\n                <option value=\"uncertain\">Requiere revisión</option>\n                <option value=\"pending\">En curso</option>\n                <option value=\"closed\">Revisión cerrada</option>\n              </select></label\n            >\n          </div>\n          <div class=\"px-6 pt-3 flex justify-between gap-3 text-xs\">\n            <span>Últimos 200 registros · retención de 30 días</span\n            ><button @click=\"exportActivity()\" class=\"font-semibold underline\">\n              Exportar historial CSV\n            </button>\n          </div>\n          <ul class=\"mt-3 pb-2\">\n            <template\n              x-for=\"(a, i) in visibleActivity\"\n              :key=\"i + a.title + a.time\"\n            >\n              <li\n                class=\"flex flex-wrap items-start gap-3 px-4 py-3 border-b border-material-border last:border-0\"\n              >\n                <div\n                  class=\"h-9 w-9 shrink-0 bg-gray-50 flex items-center justify-center text-material-dark\"\n                >\n                  <i :class=\"a.icon\" class=\"text-sm\" aria-hidden=\"true\"></i>\n                </div>\n                <div class=\"min-w-0 flex-1\">\n                  <p\n                    class=\"text-sm font-medium text-material-dark truncate\"\n                    x-text=\"a.title\"\n                  ></p>\n                  <p class=\"text-xs text-gray-400 truncate\" x-text=\"a.meta\"></p>\n                  <p\n                    class=\"text-xs mt-1 font-mono\"\n                    x-text=\"a.code ? 'Código: ' + grouped(a.code) : 'Apertura desde el panel'\"\n                  ></p>\n                  <p class=\"text-xs mt-1\" x-text=\"a.owner\"></p>\n                </div>\n                <div class=\"text-right shrink-0\">\n                  <span\n                    class=\"inline-flex items-center gap-1 px-2 py-1 text-xs font-bold\"\n                    :class=\"a.ok ? 'bg-green-100 text-green-700' : a.outcome === 'not_sent' ? 'bg-gray-100 text-gray-700' : 'bg-amber-100 text-amber-800'\"\n                  >\n                    <i\n                      :class=\"a.ok ? 'fa-solid fa-check' : 'fa-solid fa-xmark'\"\n                      class=\"text-[10px]\"\n                      aria-hidden=\"true\"\n                    ></i\n                    ><span x-text=\"a.ok ? 'Orden enviada' : a.reason\"></span>\n                  </span>\n                  <p class=\"text-xs text-gray-500 mt-1\" x-text=\"a.time\"></p>\n                </div>\n              </li>\n            </template>\n            <li\n              x-show=\"visibleActivity.length === 0\"\n              x-cloak\n              class=\"px-6 py-8 text-center text-sm text-material-text\"\n            >\n              No hay registros con estos filtros.\n            </li>\n          </ul>\n        </div>\n      </section>\n      <section\n  x-show=\"page === 'profile'\"\n  x-cloak\n  data-panel-page=\"profile\"\n  class=\"max-w-xl mx-auto w-full\"\n  x-data=\"profilePanel\"\n  x-init=\"loadProfile()\"\n>\n  <p role=\"alert\" class=\"text-sm text-red-700 mb-3\" x-text=\"profileError\"></p>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mb-4\">\n    <h2 class=\"text-xl font-bold text-material-dark\">Mi perfil</h2>\n    <p class=\"text-sm mt-2 text-material-text\">\n      Tu cuenta es la misma para todos tus edificios.\n    </p>\n    <p class=\"text-xs mt-5 text-material-text\">Teléfono</p>\n    <p class=\"font-medium break-all mt-1\" x-text=\"phone\"></p>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mb-4\">\n    <h3 class=\"font-bold\">Cambiar teléfono</h3>\n    <p class=\"text-sm my-3\">\n      Se actualizará en todos tus edificios y se cerrará tu sesión. Incluye el\n      código de país.\n    </p>\n    <form\n      @submit.prevent=\"saveProfilePhone()\"\n      x-show=\"!phoneSaved && !passwordSaved\"\n      class=\"space-y-4\"\n    >\n      <label class=\"block text-sm\"\n        >Nuevo teléfono<input\n          type=\"tel\"\n          x-model=\"newPhone\"\n          required\n          class=\"field\"\n          placeholder=\"+52 55 1234 5678\" /></label\n      ><label class=\"block text-sm\"\n        >Contraseña para cambiar teléfono<input\n          type=\"password\"\n          x-model=\"phoneSecret\"\n          required\n          autocomplete=\"current-password\"\n          class=\"field\" /></label\n      ><button\n        class=\"w-full bg-material-dark text-white px-4 py-3\"\n        :disabled=\"profileBusy\"\n      >\n        Guardar teléfono\n      </button>\n    </form>\n    <div x-show=\"phoneSaved\" role=\"status\">\n      <p>Teléfono actualizado.</p>\n      <a href=\"/login\" class=\"underline\"\n        >Iniciar sesión con el nuevo teléfono</a\n      >\n    </div>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6\">\n    <h3 class=\"font-bold text-material-dark\">Cambiar contraseña</h3>\n    <p class=\"text-sm mt-2 mb-4\">\n      Por seguridad, al guardarla tendrás que iniciar sesión de nuevo.\n    </p>\n    <form\n      @submit.prevent=\"saveProfilePassword()\"\n      x-show=\"!passwordSaved && !phoneSaved\"\n      class=\"space-y-4\"\n    >\n      <label class=\"block text-sm\"\n        >Contraseña actual<input\n          type=\"password\"\n          x-model=\"currentSecret\"\n          autocomplete=\"current-password\"\n          required\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><label class=\"block text-sm\"\n        >Nueva contraseña<input\n          type=\"password\"\n          x-model=\"secret\"\n          autocomplete=\"new-password\"\n          required\n          minlength=\"8\"\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><label class=\"block text-sm\"\n        >Repetir nueva contraseña<input\n          type=\"password\"\n          x-model=\"confirmSecret\"\n          autocomplete=\"new-password\"\n          required\n          minlength=\"8\"\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><button\n        type=\"submit\"\n        :disabled=\"profileBusy\"\n        class=\"w-full bg-material-dark text-white px-4 py-3 font-medium disabled:opacity-50\"\n      >\n        Guardar contraseña\n      </button>\n    </form>\n    <div x-show=\"passwordSaved\" role=\"status\" class=\"bg-green-50 p-4 text-sm\">\n      <p>Contraseña actualizada. Inicia sesión con tu nueva contraseña.</p>\n      <a\n        href=\"/login\"\n        class=\"inline-block mt-3 bg-material-dark text-white px-4 py-3\"\n        >Volver a iniciar sesión</a\n      >\n    </div>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mt-4\">\n    <h3 class=\"font-bold\">PortonSmart en tu celular</h3>\n    <p class=\"text-sm my-3\">\n      Agrega el icono a inicio para entrar más fácilmente. Necesitas internet\n      para usar los accesos.\n    </p>\n    <button\n      type=\"button\"\n      data-install-app\n      class=\"bg-material-dark text-white px-4 py-3\"\n    >\n      Instalar en mi celular\n    </button>\n  </div>\n</section>\n\n      <p x-show=\"page !== 'profile'\" class=\"text-xs mt-5\">\n        Una orden confirmada no garantiza el movimiento físico del portón.\n        Comprueba la apertura a la vista.\n      </p>\n    </div>\n  </main>\n  <!-- NUEVO PASE -->\n  <div\n    x-trap.inert.noscroll=\"sheet\"\n    x-show=\"sheet\"\n    x-cloak\n    class=\"fixed inset-0 z-50 flex items-end md:items-center justify-center\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-labelledby=\"sheet-title\"\n  >\n    <div\n      class=\"absolute inset-0 bg-black/40\"\n      @click=\"sheet = false\"\n      x-transition.opacity\n    ></div>\n    <form\n      @submit.prevent=\"createCode()\"\n      novalidate\n      class=\"relative bg-white w-full md:max-w-md shadow-floating max-h-[92vh] overflow-y-auto\"\n      x-show=\"sheet\"\n      x-transition:enter=\"transition duration-200\"\n      x-transition:enter-start=\"translate-y-6 opacity-0\"\n      x-transition:enter-end=\"translate-y-0 opacity-100\"\n    >\n      <div class=\"px-6 py-4 bg-material-dark flex items-center justify-between\">\n        <h2 id=\"sheet-title\" class=\"text-white font-bold\">Nuevo código</h2>\n        <button\n          type=\"button\"\n          @click=\"sheet = false\"\n          class=\"on-dark text-white/80 hover:text-white w-8 h-8\"\n          aria-label=\"Cerrar\"\n        >\n          <i class=\"fa-solid fa-xmark\"></i>\n        </button>\n      </div>\n      <div class=\"p-6 space-y-5\">\n        <div>\n          <label for=\"f-name\" class=\"text-sm font-medium text-material-dark\"\n            >Nombre o referencia</label\n          >\n          <input\n            id=\"f-name\"\n            x-ref=\"name\"\n            x-model=\"passName\"\n            type=\"text\"\n            placeholder=\"Ej. María López\"\n            autocomplete=\"off\"\n            class=\"mt-1.5 w-full border border-gray-300 px-3 py-2.5 text-sm text-material-dark placeholder-gray-400 focus:border-material-dark\"\n            :aria-invalid=\"formError && !form.name.trim() ? 'true' : 'false'\"\n          />\n        </div>\n\n        <fieldset>\n          <legend class=\"text-sm font-medium text-material-dark\">Tipo</legend>\n          <div class=\"mt-2 grid grid-cols-3\">\n            <template\n              x-for=\"o in [['repeat','Con vigencia'],['visit','Un solo uso'],['unlimited','Permanente']]\"\n              :key=\"o[0]\"\n              ><label class=\"cursor-pointer\"\n                ><input\n                  type=\"radio\"\n                  name=\"mode\"\n                  class=\"peer sr-only\"\n                  :value=\"o[0]\"\n                  x-model=\"passMode\" /><span\n                  class=\"block text-center border border-gray-300 py-3 text-sm peer-checked:bg-material-dark peer-checked:text-white peer-focus-visible:outline\"\n                  x-text=\"o[1]\"\n                ></span></label\n            ></template>\n          </div>\n          <p x-show=\"form.mode === 'visit'\" class=\"text-xs mt-3\">\n            Tienes 7 días para comenzar la visita. Desde el primer envío tendrás\n            10 minutos para volver a abrir, incluso si no llega la confirmación.\n          </p>\n          <p x-show=\"form.mode === 'unlimited'\" class=\"text-xs mt-3\">\n            Funciona hasta que lo revoques.\n          </p>\n        </fieldset>\n        <fieldset x-show=\"form.mode === 'repeat'\">\n          <legend class=\"text-sm font-medium text-material-dark\">\n            Vigencia\n          </legend>\n          <div class=\"mt-2 grid grid-cols-3\">\n            <template\n              x-for=\"o in [['1','1 día'],['7','7 días'],['custom','Otra cantidad']]\"\n              :key=\"o[0]\"\n              ><label class=\"cursor-pointer\"\n                ><input\n                  type=\"radio\"\n                  name=\"duration\"\n                  class=\"peer sr-only\"\n                  :value=\"o[0]\"\n                  x-model=\"durationDays\" /><span\n                  class=\"block text-center border border-gray-300 py-3 text-sm peer-checked:bg-material-dark peer-checked:text-white peer-focus-visible:outline\"\n                  x-text=\"o[1]\"\n                ></span></label\n            ></template>\n          </div>\n          <div x-show=\"durationDays === 'custom'\" class=\"mt-3\">\n            <label for=\"custom-days\" class=\"text-sm\"\n              >Cantidad de días (1 a 30)</label\n            ><input\n              id=\"custom-days\"\n              type=\"number\"\n              min=\"1\"\n              max=\"30\"\n              step=\"1\"\n              x-model.number=\"customDays\"\n              class=\"mt-2 w-full border border-gray-300 p-3\"\n            />\n          </div>\n        </fieldset>\n\n        <fieldset>\n          <legend class=\"text-sm font-medium text-material-dark\">\n            Accesos permitidos\n          </legend>\n          <div class=\"mt-1.5 space-y-2\">\n            <template x-for=\"d in doors\" :key=\"d.id\"\n              ><label class=\"flex items-center gap-3 text-sm text-material-dark\"\n                ><input\n                  type=\"checkbox\"\n                  x-model=\"passDoors\"\n                  :value=\"d.id\"\n                  class=\"w-4 h-4 accent-[#344767]\" /><span\n                  x-text=\"d.name\"\n                ></span></label\n            ></template>\n          </div>\n        </fieldset>\n\n        <p\n          x-show=\"formError\"\n          x-cloak\n          class=\"text-sm text-red-600 flex items-center gap-2\"\n          role=\"alert\"\n        >\n          <i class=\"fa-solid fa-circle-exclamation\" aria-hidden=\"true\"></i\n          ><span x-text=\"formError\"></span>\n        </p>\n      </div>\n      <div class=\"px-6 pb-6 flex gap-3\">\n        <button\n          type=\"button\"\n          @click=\"sheet = false\"\n          class=\"flex-1 py-3 border border-gray-300 text-sm font-semibold text-material-dark hover:bg-gray-50\"\n        >\n          Cancelar\n        </button>\n        <button\n          type=\"submit\"\n          :disabled=\"busy\"\n          class=\"flex-1 py-3 bg-material-dark text-white text-sm font-semibold hover:bg-material-darker\"\n        >\n          Crear código\n        </button>\n      </div>\n    </form>\n  </div>\n\n  <div\n    x-show=\"confirmTarget\"\n    x-cloak\n    x-trap.inert.noscroll=\"confirmTarget\"\n    class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-label=\"Confirmar apertura\"\n  >\n    <div class=\"bg-white shadow-floating w-full max-w-md\">\n      <h2 class=\"bg-material-dark text-white font-bold px-6 py-4\">\n        Confirmar apertura\n      </h2>\n      <div class=\"p-6\">\n        <p>¿Enviar una orden a <strong x-text=\"confirmName\"></strong>?</p>\n        <div class=\"flex justify-end gap-3 mt-6\">\n          <button @click=\"confirmTarget = null\" class=\"border px-4 py-3\">\n            Cancelar</button\n          ><button\n            @click=\"confirmSend()\"\n            class=\"bg-material-dark text-white px-4 py-3\"\n          >\n            Enviar orden\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div\n    x-show=\"resultCard\"\n    x-cloak\n    x-trap.inert.noscroll=\"resultCard\"\n    class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-label=\"Código creado\"\n  >\n    <div class=\"bg-white shadow-floating w-full max-w-md\">\n      <h2 class=\"bg-material-dark text-white font-bold px-6 py-4\">\n        Código creado\n      </h2>\n      <template x-if=\"resultCard\"\n        ><div class=\"p-6\">\n          <h3 class=\"font-bold\" x-text=\"resultCard.name\"></h3>\n          <p\n            class=\"font-mono text-3xl my-4\"\n            x-text=\"grouped(resultCard.code)\"\n          ></p>\n          <p x-text=\"resultCard.type\"></p>\n          <p class=\"text-sm mt-2\" x-text=\"accessLabel(resultCard)\"></p>\n          <p class=\"text-sm mt-2\" x-text=\"expiryText(resultCard)\"></p>\n          <p x-show=\"resultCard.visit\" class=\"text-xs mt-3\">\n            Una visita: 10 minutos para reintentar desde el primer envío,\n            incluso si no llega la confirmación.\n          </p>\n          <div class=\"grid grid-cols-2 gap-3 mt-6\">\n            <button @click=\"copy(resultCard)\" class=\"border p-3 text-sm\">\n              Copiar código</button\n            ><button\n              @click=\"share(resultCard)\"\n              class=\"bg-material-dark text-white p-3 text-sm\"\n            >\n              Compartir por WhatsApp\n            </button>\n          </div>\n          <button @click=\"resultCard = null\" class=\"w-full mt-4 p-2 text-sm\">\n            Cerrar\n          </button>\n        </div></template\n      >\n    </div>\n  </div>\n  <!-- TOAST -->\n  <div\n    x-show=\"toastOn\"\n    x-cloak\n    x-transition.opacity\n    role=\"status\"\n    aria-live=\"polite\"\n    class=\"fixed z-50 bottom-24 md:bottom-6 left-1/2 -translate-x-1/2 bg-material-dark text-white text-sm px-4 py-3 shadow-floating flex items-center gap-2\"\n  >\n    <i class=\"fa-solid fa-circle-check text-emerald-400\" aria-hidden=\"true\"></i\n    ><span x-text=\"toastMsg\"></span>\n  </div>\n  <div\n    x-show=\"userModal\"\n    x-cloak\n    x-trap.inert.noscroll=\"userModal\"\n    class=\"admin-modal\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-labelledby=\"user-title\"\n  >\n    <form @submit.prevent=\"saveUser()\" class=\"admin-modal-card\">\n      <h2 id=\"user-title\" class=\"modal-title\" x-text=\"modalTitle\"></h2>\n      <div class=\"p-6 space-y-4\">\n        <label x-show=\"modalKind === 'create'\" class=\"block text-sm\"\n          >Usuario<input\n            x-model=\"userName\"\n            :required=\"modalKind === 'create'\"\n            :disabled=\"modalKind !== 'create'\"\n            class=\"field\"\n            autocomplete=\"off\" /></label\n        ><label x-show=\"modalKind === 'create'\" class=\"block text-sm\"\n          >Teléfono (con código de país)<input\n            type=\"tel\"\n            x-model=\"userPhone\"\n            :required=\"modalKind === 'create'\"\n            :disabled=\"modalKind !== 'create'\"\n            class=\"field\"\n            autocomplete=\"off\" /></label\n        ><label x-show=\"modalKind !== 'permissions'\" class=\"block text-sm\"\n          >Contraseña (mínimo 8 caracteres)<input\n            type=\"password\"\n            x-model=\"userPassword\"\n            minlength=\"8\"\n            maxlength=\"128\"\n            :required=\"modalKind !== 'permissions'\"\n            :disabled=\"modalKind === 'permissions'\"\n            class=\"field\"\n            autocomplete=\"new-password\"\n        /></label>\n        <fieldset>\n          <legend class=\"text-sm font-semibold\">Accesos permitidos</legend>\n          <template x-for=\"d in doors\" :key=\"d.id\"\n            ><label class=\"flex gap-3 items-center py-2 text-sm\"\n              ><input type=\"checkbox\" :value=\"d.id\" x-model=\"userGates\" /><span\n                x-text=\"d.name\"\n              ></span></label\n          ></template>\n          <p x-show=\"doors.length === 0\" class=\"text-xs\">\n            Sin portones habilitados; la cuenta quedará sin acceso.\n          </p>\n        </fieldset>\n        <p x-show=\"modalKind === 'permissions'\" class=\"text-xs\">\n          Quitar un acceso revoca los códigos activos asociados.\n        </p>\n        <p\n          x-show=\"userError\"\n          x-text=\"userError\"\n          role=\"alert\"\n          class=\"text-sm text-red-700\"\n        ></p>\n        <div class=\"flex justify-end gap-3\">\n          <button type=\"button\" @click=\"cancelUser()\" class=\"mini-action\">\n            Cancelar</button\n          ><button\n            :disabled=\"busy\"\n            class=\"bg-material-dark text-white px-4 py-3 text-sm\"\n          >\n            Guardar\n          </button>\n        </div>\n      </div>\n    </form>\n  </div>\n  <div\n    x-show=\"welcome\"\n    x-cloak\n    x-trap.inert.noscroll=\"welcome\"\n    class=\"admin-modal\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-label=\"Compartir acceso\"\n  >\n    <div class=\"admin-modal-card\">\n      <h2 class=\"modal-title\" x-text=\"welcome ? welcome.title : ''\"></h2>\n      <div class=\"p-6\">\n        <p\n          class=\"text-sm whitespace-pre-wrap break-words\"\n          x-text=\"welcome ? welcome.text : ''\"\n        ></p>\n        <a\n          :href=\"welcomeLink\"\n          target=\"_blank\"\n          rel=\"noopener noreferrer\"\n          class=\"block bg-material-dark text-white text-center py-3 mt-5 text-sm\"\n          >Compartir bienvenida por WhatsApp</a\n        ><button @click=\"welcome = null\" class=\"mini-action mt-3 w-full\">\n          Cerrar\n        </button>\n      </div>\n    </div>\n  </div>\n  <div\n    x-show=\"actionConfirmation\"\n    x-cloak\n    x-trap.inert.noscroll=\"actionConfirmation\"\n    class=\"admin-modal\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-label=\"Confirmar cambio\"\n  >\n    <div class=\"admin-modal-card\">\n      <h2 class=\"modal-title\" x-text=\"confirmTitle\"></h2>\n      <div class=\"p-6\">\n        <p class=\"text-sm\" x-text=\"confirmMessage\"></p>\n        <div class=\"flex justify-end gap-3 mt-5\">\n          <button\n            @click=\"actionConfirmation = null\"\n            :disabled=\"confirmBusy\"\n            class=\"mini-action\"\n          >\n            Cancelar</button\n          ><button\n            @click=\"confirmAction()\"\n            :disabled=\"confirmBusy\"\n            class=\"bg-red-700 text-white px-4 py-3 text-sm\"\n          >\n            Confirmar\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div\n    x-show=\"settingsOpen\"\n    x-cloak\n    x-trap.inert.noscroll=\"settingsOpen\"\n    @keydown.escape.window=\"settingsOpen = false\"\n    class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-labelledby=\"settings-title\"\n  >\n    <form\n      @submit.prevent=\"saveSettings()\"\n      class=\"bg-white shadow-floating w-full max-w-md\"\n    >\n      <h2\n        id=\"settings-title\"\n        class=\"bg-material-dark text-white font-bold px-6 py-4\"\n      >\n        Configuración del edificio\n      </h2>\n      <div class=\"p-6 space-y-4\">\n        <p class=\"text-sm\">Contacto de ayuda para residentes y visitantes.</p>\n        <label class=\"block text-sm\"\n          >Teléfono de WhatsApp<input\n            type=\"tel\"\n            x-model=\"supportPhone\"\n            class=\"mt-2 w-full border border-gray-300 p-2\"\n            placeholder=\"Código de país y número\"\n        /></label>\n        <p class=\"text-xs\">\n          Incluye el código de país. Déjalo vacío para retirar el contacto. La\n          conexión y asignación de relés se administran desde la plataforma del\n          superadministrador.\n        </p>\n        <p\n          x-show=\"settingsMessage\"\n          x-text=\"settingsMessage\"\n          role=\"status\"\n          class=\"text-sm text-green-700\"\n        ></p>\n        <div class=\"flex justify-end gap-3\">\n          <button\n            type=\"button\"\n            @click=\"settingsOpen = false\"\n            class=\"border px-4 py-2\"\n          >\n            Cerrar</button\n          ><button\n            :disabled=\"busy\"\n            class=\"bg-material-dark text-white px-4 py-2\"\n          >\n            Guardar configuración\n          </button>\n        </div>\n      </div>\n    </form>\n  </div>\n</body>\n","resident":"<body\n  @open-profile.window=\"goTo('profile')\"\n  class=\"app-shell bg-material-bg text-material-text flex overflow-hidden font-sans antialiased\"\n  x-data=\"resident\"\n  @keydown.escape.window=\"closePanels()\"\n>\n  <!-- SIDEBAR / DRAWER -->\n  <aside\n    :class=\"drawer ? 'translate-x-0' : '-translate-x-full md:translate-x-0'\"\n    class=\"app-sidebar fixed md:relative inset-y-0 left-0 z-40 w-64 bg-white flex flex-col shrink-0 shadow-soft transition-transform duration-300 -translate-x-full md:translate-x-0\"\n    style=\"height: 100dvh\"\n    aria-label=\"Menú principal\"\n  >\n    <div class=\"h-20 flex items-center px-6\">\n      <div\n        class=\"w-9 h-9 bg-material-dark flex items-center justify-center text-white shadow-floating\"\n      >\n        <i class=\"fa-solid fa-building-shield text-sm\" aria-hidden=\"true\"></i>\n      </div>\n      <span class=\"ml-3 text-material-dark text-sm font-bold tracking-wider\"\n        >PORTONSMART</span\n      >\n    </div>\n    <hr class=\"border-material-border mx-4 mb-4\" />\n    <nav class=\"flex-1 min-h-0 px-4 overflow-y-auto scrollbar-thin\">\n      <div\n        x-data=\"buildingPicker\"\n        x-show=\"linked && options.length > 1\"\n        class=\"px-3 py-3 mb-3 bg-white text-material-dark border border-gray-200\"\n      >\n        <label x-show=\"linked && options.length > 1\" class=\"block text-xs\"\n          >Edificio que controlas<select\n            x-ref=\"buildingSelect\"\n            x-model=\"selected\"\n            @change=\"change()\"\n            class=\"w-full mt-2 border p-2 text-sm\"\n          >\n            <template x-for=\"o in options\" :key=\"o.url\"\n              ><option :value=\"o.url\" x-text=\"o.label\"></option\n            ></template></select\n        ></label>\n      </div>\n      <a\n        x-show=\"user.role === 'master'\"\n        :href=\"dashboardUrl\"\n        class=\"block px-3 py-3 mb-2 text-sm text-material-dark\"\n        >← Panel de administración</a\n      >\n      <p class=\"px-3 text-xs font-medium text-material-text mb-2\">Mi cuenta</p>\n      <a\n        href=\"#accesos\"\n        @click.prevent=\"selectTab('accesos')\"\n        :aria-current=\"page === 'accesos' ? 'page' : null\"\n        :class=\"page === 'accesos' ? 'bg-material-dark text-white shadow-floating' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-door-open\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Mis accesos</span>\n      </a>\n      <a\n        href=\"#pases\"\n        @click.prevent=\"selectTab('pases')\"\n        :aria-current=\"page === 'pases' ? 'page' : null\"\n        :class=\"page === 'pases' ? 'bg-material-dark text-white shadow-floating' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-qrcode\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Códigos activos</span>\n      </a>\n      <a\n        href=\"#actividad\"\n        @click.prevent=\"selectTab('actividad')\"\n        :aria-current=\"page === 'actividad' ? 'page' : null\"\n        :class=\"page === 'actividad' ? 'bg-material-dark text-white shadow-floating' : 'text-material-dark hover:bg-gray-50'\"\n        class=\"flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i\n            class=\"fa-solid fa-clock-rotate-left\"\n            aria-hidden=\"true\"\n          ></i></span\n        ><span class=\"ml-2\">Historial</span>\n      </a>\n\n      <p class=\"px-3 text-xs font-medium text-material-text mt-6 mb-2\">Ayuda</p>\n      <a\n        href=\"#\"\n        @click.prevent=\"support()\"\n        class=\"flex items-center px-3 py-3 text-material-dark hover:bg-gray-50 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-circle-question\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Soporte</span>\n      </a>\n    </nav>\n    <div class=\"p-4 border-t border-material-border\">\n      <a\n        href=\"?section=profile\"\n        @click.prevent=\"goTo('profile')\"\n        aria-label=\"Mi perfil\"\n        class=\"bg-gray-50 p-3 flex items-center gap-3 hover:bg-gray-100\"\n      >\n        <div\n          class=\"w-9 h-9 bg-material-dark flex items-center justify-center text-white text-xs font-bold\"\n          aria-hidden=\"true\"\n          x-text=\"initials\"\n        ></div>\n        <div class=\"flex-1 min-w-0\">\n          <p class=\"text-xs font-semibold text-material-dark truncate\">\n            <span x-text=\"user.username\"></span>\n          </p>\n          <p class=\"text-xs text-material-text truncate\">\n            <span\n              x-text=\"user.role === 'master' ? 'Administración' : 'Residente'\"\n            ></span>\n          </p>\n        </div>\n        <i class=\"fa-solid fa-chevron-right text-xs\" aria-hidden=\"true\"></i\n      ></a>\n    </div>\n    <div class=\"sidebar-session\">\n  <button type=\"button\" @click=\"logout()\" class=\"sidebar-logout\">\n    <i class=\"fa-solid fa-right-from-bracket\" aria-hidden=\"true\"></i\n    ><span>Cerrar sesión</span>\n  </button>\n</div>\n\n  </aside>\n  <div\n    x-show=\"drawer\"\n    x-cloak\n    @click=\"drawer = false\"\n    class=\"fixed inset-0 bg-black/30 z-30 md:hidden\"\n    x-transition.opacity\n  ></div>\n\n  <div\n    x-show=\"error\"\n    x-cloak\n    role=\"alert\"\n    class=\"fixed top-4 left-1/2 -translate-x-1/2 z-[80] bg-red-50 border border-red-200 text-red-800 p-4 shadow-floating max-w-[90vw]\"\n  >\n    <span x-text=\"error\"></span\n    ><button @click=\"error = ''\" class=\"ml-4 underline\">Cerrar</button>\n  </div>\n  <!-- MAIN -->\n  <main\n    id=\"main-scroll\"\n    class=\"flex-1 flex flex-col h-full overflow-y-auto relative scrollbar-thin pb-24 md:pb-8\"\n  >\n    <header\n      class=\"py-4 px-5 md:px-8 flex justify-between items-center sticky top-0 z-20 bg-material-bg/85 backdrop-blur-sm\"\n    >\n      <div>\n        <p class=\"text-sm text-gray-500\">\n          <span x-text=\"tenant.name\"></span> ·\n          <span\n            x-text=\"user.role === 'master' ? 'Administración' : 'Residente'\"\n          ></span>\n        </p>\n        <h1 class=\"font-bold text-material-dark text-xl\">\n          <span x-text=\"'Hola, ' + user.username\"></span>\n        </h1>\n      </div>\n      <button\n        @dblclick=\"refresh()\"\n        class=\"relative w-10 h-10 bg-white shadow-soft flex items-center justify-center text-material-dark\"\n        @click=\"notifications()\"\n        aria-label=\"Notificaciones\"\n      >\n        <i class=\"fa-regular fa-bell text-sm\" aria-hidden=\"true\"></i>\n        <span\n          x-show=\"noticeCount > 0\"\n          class=\"absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full\"\n        ></span>\n      </button>\n    </header>\n\n    <div class=\"px-4 md:px-8 pt-3 max-w-7xl mx-auto w-full\">\n      <div class=\"flex justify-end mb-3\">\n        <button\n          @click=\"refresh()\"\n          :disabled=\"busy\"\n          class=\"text-xs text-material-dark underline\"\n        >\n          Actualizar datos\n        </button>\n      </div>\n      <!-- ABRIR -->\n      <section\n        x-show=\"page === 'accesos'\"\n        x-cloak\n        data-panel-page=\"accesos\"\n        id=\"accesos\"\n        aria-labelledby=\"t-abrir\"\n      >\n        <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4\">\n          <h2 id=\"t-abrir\" class=\"text-base font-bold text-material-dark\">\n            Mis accesos\n          </h2>\n          <button\n            type=\"button\"\n            @click=\"openSheet()\"\n            :disabled=\"loading || busy || doors.length === 0\"\n            class=\"w-full sm:w-auto bg-material-dark text-white px-4 py-3 text-sm font-semibold shadow-soft hover:bg-slate-700 disabled:opacity-50\"\n          >\n            <i class=\"fa-solid fa-plus mr-2\" aria-hidden=\"true\"></i>Crear código\n            de visita\n          </button>\n        </div>\n        <p\n          x-show=\"!loading && doors.length === 0\"\n          class=\"bg-white p-5 mb-6 text-sm\"\n        >\n          No tienes accesos asignados. Contacta al administrador.\n        </p>\n        <div\n          class=\"grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3 md:gap-4\"\n        >\n          <template x-for=\"d in doors\" :key=\"d.id\">\n            <article class=\"relative bg-white shadow-soft\">\n              <div\n                class=\"absolute top-3 right-3 w-9 h-9 bg-material-dark flex items-center justify-center text-white\"\n              >\n                <svg\n                  viewBox=\"0 0 24 24\"\n                  class=\"w-5 h-5\"\n                  :class=\"d.state === 'abierto' ? 'gate-open' : ''\"\n                  fill=\"none\"\n                  stroke=\"currentColor\"\n                  stroke-width=\"1.8\"\n                  aria-hidden=\"true\"\n                >\n                  <path d=\"M2 21V3h20v18\" />\n                  <path class=\"gate-left\" d=\"M4 6h8v14H4zM8 6v14\" />\n                  <path class=\"gate-right\" d=\"M12 6h8v14h-8zM16 6v14\" />\n                </svg>\n              </div>\n              <div class=\"p-3 pr-14 pb-2\">\n                <h3\n                  class=\"text-base font-bold text-material-dark leading-snug\"\n                  x-text=\"d.name\"\n                ></h3>\n                <p class=\"mt-1 text-xs flex items-center gap-1.5\">\n                  <span\n                    class=\"w-1.5 h-1.5 rounded-full\"\n                    :class=\"d.online ? 'bg-emerald-500' : 'bg-red-500'\"\n                  ></span>\n                  <span x-text=\"statusLine(d)\"></span>\n                </p>\n              </div>\n              <div class=\"px-3 pb-2\">\n                <button\n                  type=\"button\"\n                  class=\"hold relative w-full h-[52px] overflow-hidden border font-bold text-sm transition-colors\"\n                  :class=\"btnClass(d)\"\n                  :disabled=\"!d.online || d.state === 'abriendo' || d.state === 'abierto'\"\n                  :aria-label=\"'Abrir ' + d.name + '. ' + label(d)\"\n                  @pointerdown.prevent=\"startHold(d.id)\"\n                  @pointerup=\"cancelHold(d.id)\"\n                  @pointerleave=\"cancelHold(d.id)\"\n                  @pointercancel=\"cancelHold(d.id)\"\n                  @blur=\"cancelHold(d.id)\"\n                  @contextmenu.prevent\n                  @keydown.enter.prevent=\"startHold(d.id)\"\n                  @keydown.space.prevent=\"startHold(d.id)\"\n                  @keyup.enter=\"cancelHold(d.id)\"\n                  @keyup.space=\"cancelHold(d.id)\"\n                >\n                  <!-- Relleno: avanza como un portón que se desliza -->\n                  <span\n                    class=\"absolute inset-y-0 left-0\"\n                    :class=\"fillClass(d)\"\n                    :style=\"'width:' + (d.progress) + '%; transition: ' + (d.state === 'sosteniendo' ? 'none' : 'width .25s ease')\"\n                  ></span>\n                  <!-- Texto oscuro (parte aún sin llenar) -->\n                  <span\n                    class=\"absolute inset-0 flex items-center justify-center gap-2 px-4\"\n                    :class=\"textClass(d)\"\n                    :style=\"'clip-path: inset(0 0 0 ' + (d.progress) + '%)'\"\n                  >\n                    <i :class=\"icon(d)\" aria-hidden=\"true\"></i\n                    ><span x-text=\"label(d)\"></span>\n                  </span>\n                  <!-- Texto claro (parte ya llena) -->\n                  <span\n                    class=\"absolute inset-0 flex items-center justify-center gap-2 px-4 text-white pointer-events-none\"\n                    aria-hidden=\"true\"\n                    :style=\"'clip-path: inset(0 ' + (100 - d.progress) + '% 0 0)'\"\n                  >\n                    <i :class=\"icon(d)\"></i><span x-text=\"label(d)\"></span>\n                  </span>\n                </button>\n                <button\n                  @click=\"confirmDoor(d)\"\n                  :disabled=\"d.state === 'abriendo'\"\n                  class=\"mt-1 w-full min-h-[40px] py-2 text-xs underline text-material-text\"\n                >\n                  Abrir con confirmación\n                </button>\n                <p x-show=\"d.hint\" x-cloak class=\"mt-2 text-xs text-amber-700\">\n                  Sigue presionando hasta que la barra se llene.\n                </p>\n              </div>\n            </article>\n          </template>\n        </div>\n        <p class=\"mt-4 text-xs text-material-text\">\n          Mantén presionado el botón para abrir. Así evitas aperturas\n          accidentales desde el bolsillo.\n        </p>\n        <p class=\"sr-only\" aria-live=\"polite\" x-text=\"live\"></p>\n      </section>\n\n      <!-- PASES -->\n      <section\n        x-show=\"page === 'pases'\"\n        x-cloak\n        data-panel-page=\"pases\"\n        id=\"pases\"\n        class=\"\"\n        aria-labelledby=\"t-pases\"\n      >\n        <div class=\"relative bg-white shadow-soft\">\n          <div\n            class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\"\n          >\n            <h2 id=\"t-pases\" class=\"text-white font-bold text-base\">\n              Códigos activos\n            </h2>\n            <button\n              @click=\"openSheet()\"\n              class=\"on-dark text-xs text-white bg-white/10 hover:bg-white/20 px-3 py-2 font-semibold flex items-center gap-1.5\"\n            >\n              <i class=\"fa-solid fa-plus text-[10px]\" aria-hidden=\"true\"></i>\n              Nuevo código\n            </button>\n          </div>\n\n          <div class=\"p-5 md:p-6 pt-6\">\n            <template x-if=\"livePasses.length === 0\">\n              <div class=\"py-10 text-center\">\n                <i\n                  class=\"fa-solid fa-qrcode text-2xl text-gray-300\"\n                  aria-hidden=\"true\"\n                ></i>\n                <p class=\"mt-3 text-sm font-medium text-material-dark\">\n                  No tienes pases activos\n                </p>\n                <p class=\"text-xs text-material-text mt-1\">\n                  Crea un pase para una visita, una entrega o un servicio.\n                </p>\n                <button\n                  @click=\"openSheet()\"\n                  class=\"mt-4 text-sm font-semibold text-white bg-material-dark px-4 py-2.5\"\n                >\n                  Crear código\n                </button>\n              </div>\n            </template>\n\n            <div class=\"compact-list\">\n  <template x-for=\"p in displayedPasses\" :key=\"p.id\">\n    <article class=\"compact-row\">\n      <details>\n        <summary class=\"compact-summary\">\n          <span class=\"compact-main\"\n            ><strong\n              class=\"code compact-code\"\n              x-text=\"grouped(p.code)\"\n            ></strong>\n            <h3 class=\"compact-name\" x-text=\"p.name\"></h3>\n            <span class=\"compact-meta\"\n              ><span class=\"gate-label\" x-text=\"accessLabel(p)\"></span\n              ><span x-text=\"p.type\"></span></span\n          ></span>\n          <span class=\"compact-state\"\n            ><span\n              class=\"state-label\"\n              :class=\"p.status === 'uncertain' || p.status === 'pending' ? 'state-warning' : p.status !== 'active' || (p.expiresAt && p.expiresAt <= now) ? 'state-muted' : expiring(p) ? 'state-warning' : 'state-active'\"\n              x-text=\"passStatus(p)\"\n            ></span\n            ><span\n              class=\"compact-expiry\"\n              x-text=\"!p.expiresAt ? 'Sin vencimiento' : p.expiresAt <= now ? 'Vencido' : 'Vence en ' + leftText(p)\"\n            ></span\n            ><span class=\"detail-toggle\"\n              >Ver detalles <span aria-hidden=\"true\">⌄</span></span\n            ></span\n          >\n        </summary>\n        <div class=\"compact-detail\">\n          <p x-text=\"expiryText(p)\"></p>\n          <p x-show=\"showPassOwner\">\n            Creado por <span x-text=\"p.owner\"></span>\n          </p>\n          <div class=\"compact-actions\">\n            <button\n              x-show=\"!p.codeMasked\"\n              @click=\"copy(p)\"\n              class=\"py-2.5 text-xs font-medium text-material-dark hover:bg-gray-50 flex flex-col items-center gap-1\"\n              aria-label=\"Copiar código\"\n            >\n              <i class=\"fa-regular fa-copy\" aria-hidden=\"true\"></i>Copiar\n            </button>\n\n            <button\n              x-show=\"canExtend(p)\"\n              x-cloak\n              @click=\"extend(p)\"\n              class=\"py-2.5 text-xs font-medium text-material-dark hover:bg-gray-50 flex flex-col items-center gap-1\"\n              aria-label=\"Extender 30 minutos\"\n            >\n              <i class=\"fa-solid fa-clock-rotate-left\" aria-hidden=\"true\"></i\n              >+30 min\n            </button>\n            <button\n              x-show=\"canRevoke(p)\"\n              @click=\"confirmRevoke(p)\"\n              class=\"py-2.5 text-xs font-medium flex flex-col items-center gap-1\"\n              :class=\"armed === 'r' + p.id ? 'bg-red-600 text-white' : 'text-red-600 hover:bg-red-50'\"\n            >\n              <i class=\"fa-solid fa-ban\" aria-hidden=\"true\"></i\n              ><span\n                x-text=\"armed === 'r' + p.id ? '¿Seguro?' : 'Revocar'\"\n              ></span>\n            </button>\n          </div>\n        </div>\n      </details>\n      <div class=\"compact-share\" x-show=\"canShare(p)\">\n        <button\n          @click=\"share(p)\"\n          class=\"mini-action\"\n          aria-label=\"Compartir pase\"\n        >\n          Compartir\n        </button>\n      </div>\n    </article>\n  </template>\n</div>\n\n          </div>\n        </div>\n      </section>\n\n      <!-- ACTIVIDAD -->\n      <section\n        x-show=\"page === 'actividad'\"\n        x-cloak\n        data-panel-page=\"actividad\"\n        id=\"actividad\"\n        class=\"\"\n        aria-labelledby=\"t-act\"\n      >\n        <div class=\"relative bg-white shadow-soft\">\n          <div\n            class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\"\n          >\n            <h2 id=\"t-act\" class=\"text-white font-bold text-base\">\n              Actividad reciente\n            </h2>\n          </div>\n          <div class=\"px-5 md:px-6 pt-5 grid gap-3 md:grid-cols-3\">\n            <label class=\"text-xs\"\n              >Buscar en historial<input\n                x-model=\"activityQuery\"\n                type=\"search\"\n                class=\"mt-1 w-full border border-gray-300 p-2\"\n                placeholder=\"Referencia, código o usuario\" /></label\n            ><label class=\"text-xs\"\n              >Filtrar portón<select\n                aria-label=\"Filtrar portón\"\n                x-model=\"activityGate\"\n                class=\"mt-1 w-full border border-gray-300 p-2\"\n              >\n                <option value=\"\">Todos los portones</option>\n                <template x-for=\"d in doors\" :key=\"d.id\"\n                  ><option :value=\"d.id\" x-text=\"d.name\"></option\n                ></template></select></label\n            ><label class=\"text-xs\"\n              >Filtrar resultado<select\n                aria-label=\"Filtrar resultado\"\n                x-model=\"activityResult\"\n                class=\"mt-1 w-full border border-gray-300 p-2\"\n              >\n                <option value=\"\">Todos los resultados</option>\n                <option value=\"sent\">Orden enviada</option>\n                <option value=\"not_sent\">No enviada</option>\n                <option value=\"uncertain\">Requiere revisión</option>\n                <option value=\"pending\">En curso</option>\n                <option value=\"closed\">Revisión cerrada</option>\n              </select></label\n            >\n          </div>\n          <div class=\"px-6 pt-3 flex justify-between gap-3 text-xs\">\n            <span>Últimos 200 registros · retención de 30 días</span\n            ><button @click=\"exportActivity()\" class=\"font-semibold underline\">\n              Exportar historial CSV\n            </button>\n          </div>\n          <div\n            class=\"px-5 md:px-6 pt-5 flex gap-2\"\n            role=\"group\"\n            aria-label=\"Filtrar actividad\"\n          >\n            <button\n              @click=\"filter = 'todo'\"\n              :aria-pressed=\"filter === 'todo'\"\n              class=\"px-3 py-1.5 text-xs font-medium border\"\n              :class=\"filter === 'todo' ? 'bg-material-dark text-white border-material-dark' : 'border-gray-300 text-material-dark hover:bg-gray-50'\"\n            >\n              Todo\n            </button>\n            <button\n              @click=\"filter = 'rechazados'\"\n              :aria-pressed=\"filter === 'rechazados'\"\n              class=\"px-3 py-1.5 text-xs font-medium border\"\n              :class=\"filter === 'rechazados' ? 'bg-material-dark text-white border-material-dark' : 'border-gray-300 text-material-dark hover:bg-gray-50'\"\n            >\n              Rechazados <span x-text=\"rejectedCount\"></span>\n            </button>\n          </div>\n          <ul class=\"mt-3 pb-2\">\n            <template\n              x-for=\"(a, i) in visibleActivity\"\n              :key=\"i + a.title + a.time\"\n            >\n              <li\n                class=\"flex items-center gap-4 px-5 md:px-6 py-3 border-b border-material-border last:border-0\"\n              >\n                <div\n                  class=\"h-9 w-9 shrink-0 bg-gray-50 flex items-center justify-center text-material-dark\"\n                >\n                  <i :class=\"a.icon\" class=\"text-sm\" aria-hidden=\"true\"></i>\n                </div>\n                <div class=\"min-w-0 flex-1\">\n                  <p\n                    class=\"text-sm font-medium text-material-dark truncate\"\n                    x-text=\"a.title\"\n                  ></p>\n                  <p class=\"text-xs text-gray-400 truncate\" x-text=\"a.meta\"></p>\n                  <p\n                    class=\"text-xs mt-1 font-mono\"\n                    x-text=\"a.code ? 'Código: ' + grouped(a.code) : 'Apertura desde el panel'\"\n                  ></p>\n                  <p\n                    x-show=\"!a.ok\"\n                    class=\"text-xs text-red-600 mt-0.5\"\n                    x-text=\"a.reason\"\n                  ></p>\n                </div>\n                <div class=\"text-right shrink-0\">\n                  <span\n                    class=\"inline-flex items-center gap-1 px-2 py-1 text-xs font-bold\"\n                    :class=\"a.ok ? 'bg-green-100 text-green-700' : 'bg-red-100 text-red-700'\"\n                  >\n                    <i\n                      :class=\"a.ok ? 'fa-solid fa-check' : 'fa-solid fa-xmark'\"\n                      class=\"text-[10px]\"\n                      aria-hidden=\"true\"\n                    ></i\n                    ><span x-text=\"a.ok ? 'Éxito' : 'Rechazado'\"></span>\n                  </span>\n                  <p class=\"text-xs text-gray-500 mt-1\" x-text=\"a.time\"></p>\n                </div>\n              </li>\n            </template>\n            <li\n              x-show=\"visibleActivity.length === 0\"\n              x-cloak\n              class=\"px-6 py-8 text-center text-sm text-material-text\"\n            >\n              No hay registros con estos filtros.\n            </li>\n          </ul>\n        </div>\n      </section>\n      <section\n  x-show=\"page === 'profile'\"\n  x-cloak\n  data-panel-page=\"profile\"\n  class=\"max-w-xl mx-auto w-full\"\n  x-data=\"profilePanel\"\n  x-init=\"loadProfile()\"\n>\n  <p role=\"alert\" class=\"text-sm text-red-700 mb-3\" x-text=\"profileError\"></p>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mb-4\">\n    <h2 class=\"text-xl font-bold text-material-dark\">Mi perfil</h2>\n    <p class=\"text-sm mt-2 text-material-text\">\n      Tu cuenta es la misma para todos tus edificios.\n    </p>\n    <p class=\"text-xs mt-5 text-material-text\">Teléfono</p>\n    <p class=\"font-medium break-all mt-1\" x-text=\"phone\"></p>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mb-4\">\n    <h3 class=\"font-bold\">Cambiar teléfono</h3>\n    <p class=\"text-sm my-3\">\n      Se actualizará en todos tus edificios y se cerrará tu sesión. Incluye el\n      código de país.\n    </p>\n    <form\n      @submit.prevent=\"saveProfilePhone()\"\n      x-show=\"!phoneSaved && !passwordSaved\"\n      class=\"space-y-4\"\n    >\n      <label class=\"block text-sm\"\n        >Nuevo teléfono<input\n          type=\"tel\"\n          x-model=\"newPhone\"\n          required\n          class=\"field\"\n          placeholder=\"+52 55 1234 5678\" /></label\n      ><label class=\"block text-sm\"\n        >Contraseña para cambiar teléfono<input\n          type=\"password\"\n          x-model=\"phoneSecret\"\n          required\n          autocomplete=\"current-password\"\n          class=\"field\" /></label\n      ><button\n        class=\"w-full bg-material-dark text-white px-4 py-3\"\n        :disabled=\"profileBusy\"\n      >\n        Guardar teléfono\n      </button>\n    </form>\n    <div x-show=\"phoneSaved\" role=\"status\">\n      <p>Teléfono actualizado.</p>\n      <a href=\"/login\" class=\"underline\"\n        >Iniciar sesión con el nuevo teléfono</a\n      >\n    </div>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6\">\n    <h3 class=\"font-bold text-material-dark\">Cambiar contraseña</h3>\n    <p class=\"text-sm mt-2 mb-4\">\n      Por seguridad, al guardarla tendrás que iniciar sesión de nuevo.\n    </p>\n    <form\n      @submit.prevent=\"saveProfilePassword()\"\n      x-show=\"!passwordSaved && !phoneSaved\"\n      class=\"space-y-4\"\n    >\n      <label class=\"block text-sm\"\n        >Contraseña actual<input\n          type=\"password\"\n          x-model=\"currentSecret\"\n          autocomplete=\"current-password\"\n          required\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><label class=\"block text-sm\"\n        >Nueva contraseña<input\n          type=\"password\"\n          x-model=\"secret\"\n          autocomplete=\"new-password\"\n          required\n          minlength=\"8\"\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><label class=\"block text-sm\"\n        >Repetir nueva contraseña<input\n          type=\"password\"\n          x-model=\"confirmSecret\"\n          autocomplete=\"new-password\"\n          required\n          minlength=\"8\"\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><button\n        type=\"submit\"\n        :disabled=\"profileBusy\"\n        class=\"w-full bg-material-dark text-white px-4 py-3 font-medium disabled:opacity-50\"\n      >\n        Guardar contraseña\n      </button>\n    </form>\n    <div x-show=\"passwordSaved\" role=\"status\" class=\"bg-green-50 p-4 text-sm\">\n      <p>Contraseña actualizada. Inicia sesión con tu nueva contraseña.</p>\n      <a\n        href=\"/login\"\n        class=\"inline-block mt-3 bg-material-dark text-white px-4 py-3\"\n        >Volver a iniciar sesión</a\n      >\n    </div>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mt-4\">\n    <h3 class=\"font-bold\">PortonSmart en tu celular</h3>\n    <p class=\"text-sm my-3\">\n      Agrega el icono a inicio para entrar más fácilmente. Necesitas internet\n      para usar los accesos.\n    </p>\n    <button\n      type=\"button\"\n      data-install-app\n      class=\"bg-material-dark text-white px-4 py-3\"\n    >\n      Instalar en mi celular\n    </button>\n  </div>\n</section>\n\n    </div>\n  </main>\n\n  <!-- NAV INFERIOR (móvil) -->\n  <nav\n    class=\"md:hidden fixed bottom-0 inset-x-0 z-30 bg-white border-t border-material-border shadow-floating\"\n    style=\"padding-bottom: env(safe-area-inset-bottom)\"\n    aria-label=\"Navegación rápida\"\n  >\n    <ul class=\"grid grid-cols-4\">\n      <template\n        x-for=\"i in [['accesos','Accesos','fa-door-open'],['pases','Pases','fa-qrcode'],['actividad','Historial','fa-clock-rotate-left']]\"\n        :key=\"i[0]\"\n      >\n        <li>\n          <a\n            :href=\"'#' + i[0]\"\n            @click.prevent=\"selectTab(i[0])\"\n            :aria-current=\"tab === i[0] ? 'page' : null\"\n            class=\"flex flex-col items-center gap-1 py-2.5 text-[11px] font-medium border-t-2\"\n            :class=\"tab === i[0] ? 'text-material-dark border-material-dark' : 'text-material-text border-transparent'\"\n          >\n            <i\n              :class=\"'fa-solid ' + i[2]\"\n              class=\"text-base\"\n              aria-hidden=\"true\"\n            ></i\n            ><span x-text=\"i[1]\"></span>\n          </a>\n        </li>\n      </template>\n      <li>\n        <button\n          @click=\"drawer = true\"\n          class=\"w-full flex flex-col items-center gap-1 py-2.5 text-[11px] font-medium text-material-text border-t-2 border-transparent\"\n        >\n          <i class=\"fa-solid fa-bars text-base\" aria-hidden=\"true\"></i>Más\n        </button>\n      </li>\n    </ul>\n  </nav>\n\n  <!-- NUEVO PASE -->\n  <div\n    x-trap.inert.noscroll=\"sheet\"\n    x-show=\"sheet\"\n    x-cloak\n    class=\"fixed inset-0 z-50 flex items-end md:items-center justify-center\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-labelledby=\"sheet-title\"\n  >\n    <div\n      class=\"absolute inset-0 bg-black/40\"\n      @click=\"sheet = false\"\n      x-transition.opacity\n    ></div>\n    <form\n      @submit.prevent=\"createCode()\"\n      novalidate\n      class=\"relative bg-white w-full md:max-w-md shadow-floating max-h-[92vh] overflow-y-auto\"\n      x-show=\"sheet\"\n      x-transition:enter=\"transition duration-200\"\n      x-transition:enter-start=\"translate-y-6 opacity-0\"\n      x-transition:enter-end=\"translate-y-0 opacity-100\"\n    >\n      <div class=\"px-6 py-4 bg-material-dark flex items-center justify-between\">\n        <h2 id=\"sheet-title\" class=\"text-white font-bold\">Nuevo código</h2>\n        <button\n          type=\"button\"\n          @click=\"sheet = false\"\n          class=\"on-dark text-white/80 hover:text-white w-8 h-8\"\n          aria-label=\"Cerrar\"\n        >\n          <i class=\"fa-solid fa-xmark\"></i>\n        </button>\n      </div>\n      <div class=\"p-6 space-y-5\">\n        <div>\n          <label for=\"f-name\" class=\"text-sm font-medium text-material-dark\"\n            >Nombre o referencia</label\n          >\n          <input\n            id=\"f-name\"\n            x-ref=\"name\"\n            x-model=\"passName\"\n            type=\"text\"\n            placeholder=\"Ej. María López\"\n            autocomplete=\"off\"\n            class=\"mt-1.5 w-full border border-gray-300 px-3 py-2.5 text-sm text-material-dark placeholder-gray-400 focus:border-material-dark\"\n            :aria-invalid=\"formError && !form.name.trim() ? 'true' : 'false'\"\n          />\n        </div>\n\n        <fieldset>\n          <legend class=\"text-sm font-medium text-material-dark\">Tipo</legend>\n          <div class=\"mt-2 grid grid-cols-3\">\n            <template\n              x-for=\"o in [['repeat','Con vigencia'],['visit','Un solo uso'],['unlimited','Permanente']]\"\n              :key=\"o[0]\"\n              ><label class=\"cursor-pointer\"\n                ><input\n                  type=\"radio\"\n                  name=\"mode\"\n                  class=\"peer sr-only\"\n                  :value=\"o[0]\"\n                  x-model=\"passMode\" /><span\n                  class=\"block text-center border border-gray-300 py-3 text-sm peer-checked:bg-material-dark peer-checked:text-white peer-focus-visible:outline\"\n                  x-text=\"o[1]\"\n                ></span></label\n            ></template>\n          </div>\n          <p x-show=\"form.mode === 'visit'\" class=\"text-xs mt-3\">\n            Tienes 7 días para comenzar la visita. Desde el primer envío tendrás\n            10 minutos para volver a abrir, incluso si no llega la confirmación.\n          </p>\n          <p x-show=\"form.mode === 'unlimited'\" class=\"text-xs mt-3\">\n            Funciona hasta que lo revoques.\n          </p>\n        </fieldset>\n        <fieldset x-show=\"form.mode === 'repeat'\">\n          <legend class=\"text-sm font-medium text-material-dark\">\n            Vigencia\n          </legend>\n          <div class=\"mt-2 grid grid-cols-3\">\n            <template\n              x-for=\"o in [['1','1 día'],['7','7 días'],['custom','Otra cantidad']]\"\n              :key=\"o[0]\"\n              ><label class=\"cursor-pointer\"\n                ><input\n                  type=\"radio\"\n                  name=\"duration\"\n                  class=\"peer sr-only\"\n                  :value=\"o[0]\"\n                  x-model=\"durationDays\" /><span\n                  class=\"block text-center border border-gray-300 py-3 text-sm peer-checked:bg-material-dark peer-checked:text-white peer-focus-visible:outline\"\n                  x-text=\"o[1]\"\n                ></span></label\n            ></template>\n          </div>\n          <div x-show=\"durationDays === 'custom'\" class=\"mt-3\">\n            <label for=\"custom-days\" class=\"text-sm\"\n              >Cantidad de días (1 a 30)</label\n            ><input\n              id=\"custom-days\"\n              type=\"number\"\n              min=\"1\"\n              max=\"30\"\n              step=\"1\"\n              x-model.number=\"customDays\"\n              class=\"mt-2 w-full border border-gray-300 p-3\"\n            />\n          </div>\n        </fieldset>\n\n        <fieldset>\n          <legend class=\"text-sm font-medium text-material-dark\">\n            Accesos permitidos\n          </legend>\n          <div class=\"mt-1.5 space-y-2\">\n            <template x-for=\"d in doors\" :key=\"d.id\"\n              ><label class=\"flex items-center gap-3 text-sm text-material-dark\"\n                ><input\n                  type=\"checkbox\"\n                  x-model=\"passDoors\"\n                  :value=\"d.id\"\n                  class=\"w-4 h-4 accent-[#344767]\" /><span\n                  x-text=\"d.name\"\n                ></span></label\n            ></template>\n          </div>\n        </fieldset>\n\n        <p\n          x-show=\"formError\"\n          x-cloak\n          class=\"text-sm text-red-600 flex items-center gap-2\"\n          role=\"alert\"\n        >\n          <i class=\"fa-solid fa-circle-exclamation\" aria-hidden=\"true\"></i\n          ><span x-text=\"formError\"></span>\n        </p>\n      </div>\n      <div class=\"px-6 pb-6 flex gap-3\">\n        <button\n          type=\"button\"\n          @click=\"sheet = false\"\n          class=\"flex-1 py-3 border border-gray-300 text-sm font-semibold text-material-dark hover:bg-gray-50\"\n        >\n          Cancelar\n        </button>\n        <button\n          type=\"submit\"\n          :disabled=\"busy\"\n          class=\"flex-1 py-3 bg-material-dark text-white text-sm font-semibold hover:bg-material-darker\"\n        >\n          Crear código\n        </button>\n      </div>\n    </form>\n  </div>\n\n  <div\n    x-show=\"confirmTarget\"\n    x-cloak\n    x-trap.inert.noscroll=\"confirmTarget\"\n    class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-label=\"Confirmar apertura\"\n  >\n    <div class=\"bg-white shadow-floating w-full max-w-md\">\n      <h2 class=\"bg-material-dark text-white font-bold px-6 py-4\">\n        Confirmar apertura\n      </h2>\n      <div class=\"p-6\">\n        <p>¿Enviar una orden a <strong x-text=\"confirmName\"></strong>?</p>\n        <div class=\"flex justify-end gap-3 mt-6\">\n          <button @click=\"confirmTarget = null\" class=\"border px-4 py-3\">\n            Cancelar</button\n          ><button\n            @click=\"confirmSend()\"\n            class=\"bg-material-dark text-white px-4 py-3\"\n          >\n            Enviar orden\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n  <div\n    x-show=\"resultCard\"\n    x-cloak\n    x-trap.inert.noscroll=\"resultCard\"\n    class=\"fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4\"\n    role=\"dialog\"\n    aria-modal=\"true\"\n    aria-label=\"Código creado\"\n  >\n    <div class=\"bg-white shadow-floating w-full max-w-md\">\n      <h2 class=\"bg-material-dark text-white font-bold px-6 py-4\">\n        Código creado\n      </h2>\n      <template x-if=\"resultCard\"\n        ><div class=\"p-6\">\n          <h3 class=\"font-bold\" x-text=\"resultCard.name\"></h3>\n          <p\n            class=\"font-mono text-3xl my-4\"\n            x-text=\"grouped(resultCard.code)\"\n          ></p>\n          <p x-text=\"resultCard.type\"></p>\n          <p class=\"text-sm mt-2\" x-text=\"accessLabel(resultCard)\"></p>\n          <p class=\"text-sm mt-2\" x-text=\"expiryText(resultCard)\"></p>\n          <p x-show=\"resultCard.visit\" class=\"text-xs mt-3\">\n            Una visita: 10 minutos para reintentar desde el primer envío,\n            incluso si no llega la confirmación.\n          </p>\n          <div class=\"grid grid-cols-2 gap-3 mt-6\">\n            <button @click=\"copy(resultCard)\" class=\"border p-3 text-sm\">\n              Copiar código</button\n            ><button\n              @click=\"share(resultCard)\"\n              class=\"bg-material-dark text-white p-3 text-sm\"\n            >\n              Compartir por WhatsApp\n            </button>\n          </div>\n          <button @click=\"resultCard = null\" class=\"w-full mt-4 p-2 text-sm\">\n            Cerrar\n          </button>\n        </div></template\n      >\n    </div>\n  </div>\n  <!-- TOAST -->\n  <div\n    x-show=\"toastOn\"\n    x-cloak\n    x-transition.opacity\n    role=\"status\"\n    aria-live=\"polite\"\n    class=\"fixed z-50 bottom-24 md:bottom-6 left-1/2 -translate-x-1/2 bg-material-dark text-white text-sm px-4 py-3 shadow-floating flex items-center gap-2\"\n  >\n    <i class=\"fa-solid fa-circle-check text-emerald-400\" aria-hidden=\"true\"></i\n    ><span x-text=\"toastMsg\"></span>\n  </div>\n</body>\n","super":"<body\n  @open-profile.window=\"goTo('profile')\"\n  class=\"app-shell bg-material-bg text-material-text flex overflow-hidden font-sans antialiased\"\n  x-data=\"superadmin\"\n  @keydown.escape.window=\"closePanels()\"\n>\n  <!-- SIDEBAR (oscuro: señal de que estás en el nivel más alto de permisos) -->\n  <aside\n    :class=\"drawer ? 'translate-x-0' : '-translate-x-full md:translate-x-0'\"\n    class=\"app-sidebar sidebar-dark fixed md:relative inset-y-0 left-0 z-40 w-64 bg-material-darker flex flex-col shrink-0 shadow-soft transition-transform duration-300 -translate-x-full md:translate-x-0\"\n    aria-label=\"Menú principal\"\n  >\n    <div class=\"h-20 flex items-center px-6 border-b border-white/10\">\n      <div\n        class=\"w-9 h-9 bg-white/10 flex items-center justify-center text-white\"\n      >\n        <i class=\"fa-solid fa-building-shield text-sm\" aria-hidden=\"true\"></i>\n      </div>\n      <span class=\"ml-3 text-white text-sm font-bold tracking-wider\"\n        >PORTONSMART</span\n      >\n    </div>\n    <nav class=\"flex-1 px-4 py-5 overflow-y-auto scrollbar-thin\">\n      <div\n        x-data=\"buildingPicker\"\n        x-show=\"linked && options.length > 1\"\n        class=\"px-3 py-3 mb-3 bg-white text-material-dark border border-gray-200\"\n      >\n        <label x-show=\"linked && options.length > 1\" class=\"block text-xs\"\n          >Edificio que controlas<select\n            x-ref=\"buildingSelect\"\n            x-model=\"selected\"\n            @change=\"change()\"\n            class=\"w-full mt-2 border p-2 text-sm\"\n          >\n            <template x-for=\"o in options\" :key=\"o.url\"\n              ><option :value=\"o.url\" x-text=\"o.label\"></option\n            ></template></select\n        ></label>\n      </div>\n      <p class=\"px-3 text-xs font-medium text-white/50 mb-2\">Plataforma</p>\n      <a\n        href=\"?section=resumen\"\n        @click.prevent=\"goTo('resumen')\"\n        :aria-current=\"page === 'resumen' ? 'page' : null\"\n        :class=\"page === 'resumen' ? 'bg-white/10 text-white' : 'text-white/80 hover:bg-white/5'\"\n        class=\"on-dark flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-gauge-high\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Resumen</span></a\n      >\n      <a\n        href=\"?section=edificios\"\n        @click.prevent=\"goTo('edificios')\"\n        :aria-current=\"page === 'edificios' ? 'page' : null\"\n        :class=\"page === 'edificios' ? 'bg-white/10 text-white' : 'text-white/80 hover:bg-white/5'\"\n        class=\"on-dark flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-city\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Edificios</span></a\n      >\n      <a\n        href=\"?section=flota\"\n        @click.prevent=\"goTo('flota')\"\n        :aria-current=\"page === 'flota' ? 'page' : null\"\n        :class=\"page === 'flota' ? 'bg-white/10 text-white' : 'text-white/80 hover:bg-white/5'\"\n        class=\"on-dark flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-microchip\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2 leading-tight\">Dispositivos y firmware</span>\n        <span\n          x-show=\"offline.length\"\n          x-cloak\n          class=\"ml-auto min-w-5 h-5 px-1 bg-amber-400 text-material-darker text-xs font-bold flex items-center justify-center\"\n          x-text=\"offline.length\"\n        ></span\n      ></a>\n      <a\n        href=\"?section=auditoria\"\n        @click.prevent=\"goTo('auditoria')\"\n        :aria-current=\"page === 'auditoria' ? 'page' : null\"\n        :class=\"page === 'auditoria' ? 'bg-white/10 text-white' : 'text-white/80 hover:bg-white/5'\"\n        class=\"on-dark flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-clipboard-list\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Auditoría</span></a\n      >\n\n      <p class=\"px-3 text-xs font-medium text-white/50 mt-6 mb-2\">Cuentas</p>\n      <a\n        href=\"?section=administradores\"\n        @click.prevent=\"goTo('administradores')\"\n        :aria-current=\"page === 'administradores' ? 'page' : null\"\n        :class=\"page === 'administradores' ? 'bg-white/10 text-white' : 'text-white/80 hover:bg-white/5'\"\n        class=\"on-dark flex items-center px-3 py-3 mt-1 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-user-tie\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Administradores</span></a\n      >\n      <a\n        href=\"?section=reports\"\n        @click.prevent=\"goTo('reports')\"\n        :aria-current=\"page === 'reports' ? 'page' : null\"\n        class=\"on-dark flex items-center px-3 py-3 mt-1 text-white/80 hover:bg-white/5 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i\n            class=\"fa-solid fa-file-invoice-dollar\"\n            aria-hidden=\"true\"\n          ></i></span\n        ><span class=\"ml-2\">Reportes</span></a\n      >\n\n      <p class=\"px-3 text-xs font-medium text-white/50 mt-6 mb-2\">Sistema</p>\n      <a\n        href=\"?section=configuration\"\n        @click.prevent=\"goTo('configuration')\"\n        :aria-current=\"page === 'configuration' ? 'page' : null\"\n        class=\"on-dark flex items-center px-3 py-3 text-white/80 hover:bg-white/5 font-medium text-sm\"\n      >\n        <span class=\"w-6 flex justify-center\"\n          ><i class=\"fa-solid fa-gear\" aria-hidden=\"true\"></i></span\n        ><span class=\"ml-2\">Configuración</span></a\n      >\n    </nav>\n    <div class=\"p-4 border-t border-white/10\">\n      <div class=\"bg-white/5 p-3\">\n        <a\n          href=\"?section=profile\"\n          @click.prevent=\"goTo('profile')\"\n          aria-label=\"Mi perfil\"\n          class=\"flex items-center gap-3 py-2\"\n        >\n          <div\n            class=\"w-9 h-9 bg-white/10 flex items-center justify-center text-white text-xs font-bold\"\n            aria-hidden=\"true\"\n            x-text=\"initials\"\n          ></div>\n          <div class=\"flex-1 min-w-0\">\n            <p\n              class=\"text-xs font-semibold text-white truncate\"\n              x-text=\"user.username\"\n            ></p>\n            <p class=\"text-xs text-white/60 truncate\">Super admin</p>\n          </div>\n          <i\n            class=\"fa-solid fa-chevron-right text-white/60 text-xs\"\n            aria-hidden=\"true\"\n          ></i\n        ></a>\n      </div>\n    </div>\n    <div class=\"sidebar-session\">\n  <button type=\"button\" @click=\"logout()\" class=\"sidebar-logout\">\n    <i class=\"fa-solid fa-right-from-bracket\" aria-hidden=\"true\"></i\n    ><span>Cerrar sesión</span>\n  </button>\n</div>\n\n  </aside>\n  <div\n    x-show=\"drawer\"\n    x-cloak\n    @click=\"drawer = false\"\n    class=\"fixed inset-0 bg-black/30 z-30 md:hidden\"\n    x-transition.opacity\n  ></div>\n\n  <!-- MAIN -->\n  <main\n    id=\"main-scroll\"\n    class=\"flex-1 flex flex-col h-full overflow-y-auto relative scrollbar-thin\"\n  >\n    <div class=\"sticky top-0 z-20 bg-material-bg/90 backdrop-blur-sm\">\n      <header class=\"py-4 px-5 md:px-8 flex justify-between items-center\">\n        <div>\n          <p class=\"text-sm text-gray-500\">Todos los edificios</p>\n          <h1\n            class=\"font-bold text-material-dark text-xl flex items-center gap-3\"\n          >\n            Super administración\n            <span\n              class=\"hidden sm:inline-block bg-material-dark text-white text-xs font-medium px-2 py-1\"\n              >Super admin</span\n            >\n          </h1>\n        </div>\n        <div class=\"flex items-center gap-2\">\n          <button\n            @click=\"goTo('pendientes')\"\n            class=\"relative w-10 h-10 bg-white shadow-soft flex items-center justify-center text-material-dark\"\n            :aria-label=\"'Notificaciones, ' + alerts.length + ' sin leer'\"\n          >\n            <i class=\"fa-regular fa-bell text-sm\" aria-hidden=\"true\"></i>\n            <span\n              x-show=\"alerts.length\"\n              x-cloak\n              class=\"absolute top-2 right-2 w-2 h-2 bg-red-500 rounded-full\"\n            ></span>\n          </button>\n          <button\n            @click=\"drawer = true\"\n            class=\"md:hidden w-10 h-10 bg-white shadow-soft flex items-center justify-center text-material-dark\"\n            aria-label=\"Abrir menú\"\n          >\n            <i class=\"fa-solid fa-bars text-sm\"></i>\n          </button>\n        </div>\n      </header>\n    </div>\n    <div class=\"px-5 md:px-8 pt-2 pb-10 max-w-7xl mx-auto w-full\">\n      <div class=\"flex justify-end mb-4\">\n        <button\n          @click=\"refresh()\"\n          :disabled=\"loading\"\n          class=\"text-sm underline\"\n        >\n          Actualizar datos\n        </button>\n      </div>\n      <p\n        x-show=\"error\"\n        x-text=\"error\"\n        role=\"alert\"\n        class=\"mb-4 p-4 bg-red-50 text-red-800\"\n      ></p>\n      <p x-show=\"loading\" role=\"status\">Cargando…</p>\n      <!-- ALERTAS -->\n      <section\n        x-show=\"page === 'resumen'\"\n        x-cloak\n        aria-label=\"Alertas\"\n        class=\"space-y-3\"\n      >\n        <template x-for=\"a in alerts\" :key=\"a.id\">\n          <div\n            class=\"bg-white shadow-soft border-l-4 border-amber-500 p-4 md:p-5 flex flex-col md:flex-row md:items-center gap-4\"\n            role=\"alert\"\n          >\n            <div\n              class=\"w-10 h-10 shrink-0 bg-amber-100 text-amber-700 flex items-center justify-center\"\n            >\n              <i\n                class=\"fa-solid fa-triangle-exclamation\"\n                aria-hidden=\"true\"\n              ></i>\n            </div>\n            <div class=\"flex-1 min-w-0\">\n              <p\n                class=\"text-sm font-bold text-material-dark\"\n                x-text=\"a.title\"\n              ></p>\n              <p class=\"text-sm text-material-text mt-0.5\" x-text=\"a.body\"></p>\n            </div>\n            <div class=\"flex gap-2 shrink-0\">\n              <button\n                @click=\"focusBuilding(a.building)\"\n                class=\"px-3 py-2 text-xs font-semibold text-white bg-material-dark hover:bg-material-darker\"\n              >\n                Ver edificio\n              </button>\n              <button\n                @click=\"dismiss(a.id)\"\n                class=\"px-3 py-2 text-xs font-semibold text-material-dark border border-gray-300 hover:bg-gray-50\"\n              >\n                Descartar\n              </button>\n            </div>\n          </div>\n        </template>\n        <p\n          x-show=\"alerts.length === 0\"\n          x-cloak\n          class=\"text-sm text-material-text flex items-center gap-2 px-1\"\n        >\n          <i\n            class=\"fa-solid fa-circle-check text-emerald-500\"\n            aria-hidden=\"true\"\n          ></i\n          >Sin incidencias conocidas. Los dispositivos sin verificar requieren\n          una consulta.\n        </p>\n      </section>\n\n      <!-- KPIs -->\n      <section\n        x-show=\"page === 'resumen'\"\n        x-cloak\n        data-panel-page=\"resumen\"\n        class=\"mt-10 grid grid-cols-2 lg:grid-cols-4 gap-x-4 gap-y-10\"\n        aria-label=\"Resumen de la plataforma\"\n      >\n        <div class=\"relative bg-white shadow-soft p-4 pt-9 sm:pt-4\">\n          <div\n            class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"\n          >\n            <i class=\"fa-solid fa-city\" aria-hidden=\"true\"></i>\n          </div>\n          <p class=\"text-sm text-gray-500\">Edificios activos</p>\n          <p\n            class=\"text-3xl font-bold text-material-dark mt-1\"\n            x-text=\"buildings.length - suspended\"\n          ></p>\n          <hr class=\"my-3 border-material-border\" />\n          <p class=\"text-xs\">\n            <span\n              class=\"font-bold text-material-dark\"\n              x-text=\"suspended\"\n            ></span>\n            suspendidos\n          </p>\n        </div>\n        <div class=\"relative bg-white shadow-soft p-4 pt-9 sm:pt-4\">\n          <div\n            class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"\n          >\n            <i class=\"fa-solid fa-tower-broadcast\" aria-hidden=\"true\"></i>\n          </div>\n          <p class=\"text-sm text-gray-500\">Dispositivos en línea</p>\n          <p class=\"text-3xl font-bold text-material-dark mt-1\">\n            <span x-text=\"devOnline\"></span\n            ><span class=\"text-lg font-medium text-gray-400\">\n              de <span x-text=\"devTotal\"></span\n            ></span>\n          </p>\n          <hr class=\"my-3 border-material-border\" />\n          <p class=\"text-xs\">\n            <span x-text=\"devOffline\"></span> desconectados ·\n            <span x-text=\"devUnknown\"></span> sin verificar\n          </p>\n        </div>\n        <div class=\"relative bg-white shadow-soft p-4 pt-9 sm:pt-4\">\n          <div\n            class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"\n          >\n            <i class=\"fa-solid fa-door-open\" aria-hidden=\"true\"></i>\n          </div>\n          <p class=\"text-sm text-gray-500\">Órdenes enviadas hoy</p>\n          <p\n            class=\"text-3xl font-bold text-material-dark mt-1\"\n            x-text=\"n(todayTotal)\"\n          ></p>\n          <hr class=\"my-3 border-material-border\" />\n          <p class=\"text-xs\">\n            <span\n              class=\"font-bold\"\n              :class=\"delta >= 0 ? 'text-green-600' : 'text-red-600'\"\n              x-text=\"(delta >= 0 ? '+' : '') + delta + '%'\"\n            ></span>\n            frente a ayer\n          </p>\n        </div>\n        <div class=\"relative bg-white shadow-soft p-4 pt-9 sm:pt-4\">\n          <div\n            class=\"absolute -top-5 right-4 w-12 h-12 bg-material-dark shadow-floating flex items-center justify-center text-white text-lg\"\n          >\n            <i class=\"fa-solid fa-microchip\" aria-hidden=\"true\"></i>\n          </div>\n          <p class=\"text-sm text-gray-500\">Pendientes de revisión</p>\n          <p class=\"text-3xl font-bold text-material-dark mt-1\">\n            <span x-text=\"pendingTotal\"></span>\n          </p>\n          <hr class=\"my-3 border-material-border\" />\n          <p class=\"text-xs\">\n            <a\n              href=\"?section=pendientes\"\n              @click.prevent=\"goTo('pendientes')\"\n              class=\"font-bold text-amber-600\"\n              >Revisar órdenes pendientes</a\n            >\n          </p>\n        </div>\n      </section>\n\n      <section\n        x-show=\"page === 'pendientes'\"\n        x-cloak\n        data-panel-page=\"pendientes\"\n        id=\"pendientes\"\n        class=\"bg-white shadow-soft p-6\"\n      >\n        <h2 class=\"font-bold text-material-dark\">Pendientes de revisión</h2>\n        <p class=\"text-sm mt-2\">\n          Comprueba lo ocurrido en el lugar antes de liberar una orden. Revisar\n          no acciona el relé.\n        </p>\n        <template x-for=\"b in pendingBuildings\" :key=\"b.id\"\n          ><div class=\"mt-3 flex justify-between gap-4 border-t pt-3\">\n            <span\n              ><strong x-text=\"b.name\"></strong> ·\n              <span x-text=\"b.pending\"></span> registros pendientes</span\n            ><button @click=\"enter(b,'review')\" class=\"text-sm underline\">\n              Revisar edificio\n            </button>\n          </div></template\n        >\n        <p x-show=\"pendingTotal === 0\" class=\"mt-3 text-sm\">\n          No hay órdenes pendientes de revisión.\n        </p>\n      </section>\n      <!-- EDIFICIOS -->\n      <section\n        x-show=\"page === 'edificios'\"\n        x-cloak\n        data-panel-page=\"edificios\"\n        id=\"edificios\"\n        class=\"\"\n        aria-labelledby=\"t-edif\"\n      >\n        <div class=\"relative bg-white shadow-soft\">\n          <div\n            class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\"\n          >\n            <h2 id=\"t-edif\" class=\"text-white font-bold text-base\">\n              Edificios\n            </h2>\n            <button\n              @click=\"openSheet()\"\n              class=\"on-dark text-xs text-white bg-white/10 hover:bg-white/20 px-3 py-2 font-semibold flex items-center gap-1.5\"\n            >\n              <i class=\"fa-solid fa-plus text-[10px]\" aria-hidden=\"true\"></i>\n              Nuevo edificio\n            </button>\n          </div>\n\n          <div\n            class=\"px-5 md:px-6 pt-5 flex flex-col md:flex-row md:items-center gap-3\"\n          >\n            <div class=\"flex\" role=\"group\" aria-label=\"Filtrar edificios\">\n              <template\n                x-for=\"o in [['todos','Todos', buildings.length],['incidencias','Con incidencias', withIssues],['suspended','Suspendidos', suspended]]\"\n                :key=\"o[0]\"\n              >\n                <button\n                  @click=\"tab = o[0]\"\n                  :aria-pressed=\"tab === o[0]\"\n                  class=\"px-3 py-2 text-xs font-medium border -ml-px first:ml-0\"\n                  :class=\"tab === o[0] ? 'bg-material-dark text-white border-material-dark' : 'border-gray-300 text-material-dark hover:bg-gray-50'\"\n                >\n                  <span x-text=\"o[1]\"></span>\n                  <span class=\"opacity-70\" x-text=\"o[2]\"></span>\n                </button>\n              </template>\n            </div>\n            <div class=\"relative md:ml-auto md:w-72\">\n              <label class=\"sr-only\" for=\"f-q\">Buscar edificio</label>\n              <i\n                class=\"fa-solid fa-magnifying-glass absolute left-3 top-1/2 -translate-y-1/2 text-xs text-gray-400\"\n                aria-hidden=\"true\"\n              ></i>\n              <input\n                id=\"f-q\"\n                x-model=\"q\"\n                type=\"search\"\n                placeholder=\"Buscar edificio o administrador\"\n                class=\"w-full border border-gray-300 pl-8 pr-3 py-2 text-xs text-material-dark placeholder-gray-400\"\n              />\n            </div>\n          </div>\n\n          <div class=\"block w-full overflow-x-auto mt-3\">\n            <table class=\"w-full text-left building-table\">\n              <thead>\n                <tr\n                  class=\"border-b border-material-border text-xs text-gray-500\"\n                >\n                  <th class=\"px-6 py-3 font-medium\">Edificio</th>\n                  <th class=\"px-6 py-3 font-medium hidden lg:table-cell\">\n                    Cuenta\n                  </th>\n                  <th class=\"px-6 py-3 font-medium text-center\">\n                    Dispositivos\n                  </th>\n                  <th class=\"px-6 py-3 font-medium hidden md:table-cell\">\n                    Órdenes enviadas hoy\n                  </th>\n                  <th class=\"px-6 py-3 font-medium\">Estado</th>\n                  <th class=\"px-6 py-3 font-medium text-right\">\n                    <span class=\"sr-only\">Acciones</span>\n                  </th>\n                </tr>\n              </thead>\n              <tbody>\n                <template x-for=\"b in filtered\" :key=\"b.id\">\n                  <tr\n                    class=\"border-b border-material-border hover:bg-gray-50/60\"\n                  >\n                    <td class=\"px-6 py-3\">\n                      <p\n                        class=\"text-sm font-semibold text-material-dark whitespace-nowrap\"\n                        x-text=\"b.name\"\n                      ></p>\n                      <p class=\"text-xs text-gray-400 whitespace-nowrap\">\n                        <span x-text=\"b.slug\"></span> ·\n                        <span x-text=\"b.admin\"></span\n                        ><span x-show=\"b.pending\"></span>\n                      </p>\n                    </td>\n                    <td class=\"px-6 py-3 hidden lg:table-cell\">\n                      <span\n                        class=\"inline-block px-2 py-1 text-xs font-bold\"\n                        :class=\"accountClass(b)\"\n                        x-text=\"b.statusLabel\"\n                      ></span>\n                    </td>\n                    <td\n                      class=\"px-6 py-3 text-center font-mono text-sm text-material-dark whitespace-nowrap\"\n                    >\n                      <template x-if=\"b.total > 0\"\n                        ><span\n                          ><span\n                            :class=\"b.online < b.total ? 'text-amber-700 font-medium' : ''\"\n                            x-text=\"b.online\"\n                          ></span>\n                          / <span x-text=\"b.total\"></span></span\n                      ></template>\n                      <span x-show=\"b.total === 0\" class=\"text-gray-400\"\n                        >—</span\n                      >\n                    </td>\n                    <td class=\"px-6 py-3 hidden md:table-cell\">\n                      <div class=\"flex items-center gap-3 min-w-[150px]\">\n                        <span\n                          class=\"font-mono text-sm text-material-dark w-10 text-right\"\n                          x-text=\"b.today\"\n                        ></span>\n                        <div class=\"h-1.5 bg-gray-100 flex-1\">\n                          <div\n                            class=\"h-1.5 bg-material-dark\"\n                            :style=\"buildingWidth(b)\"\n                          ></div>\n                        </div>\n                      </div>\n                    </td>\n                    <td class=\"px-6 py-3\">\n                      <span\n                        class=\"inline-flex items-center gap-1 px-2 py-1 text-xs font-bold whitespace-nowrap\"\n                        :class=\"health(b).c\"\n                      >\n                        <i\n                          :class=\"health(b).i\"\n                          class=\"text-[10px]\"\n                          aria-hidden=\"true\"\n                        ></i\n                        ><span x-text=\"health(b).t\"></span>\n                      </span>\n                    </td>\n                    <td class=\"px-6 py-3 text-right\">\n                      <button\n                        @click=\"enter(b)\"\n                        class=\"px-3 py-1.5 text-xs font-semibold border whitespace-nowrap\"\n                        :class=\"armed === 'e' + b.id ? 'bg-material-dark border-material-dark text-white' : 'border-gray-300 text-material-dark hover:bg-gray-50'\"\n                        x-text=\"manageLabel\"\n                      ></button>\n                    </td>\n                  </tr>\n                </template>\n              </tbody>\n            </table>\n            <div\n              x-show=\"filtered.length === 0\"\n              x-cloak\n              class=\"px-6 py-10 text-center\"\n            >\n              <p class=\"text-sm font-medium text-material-dark\">\n                No hay edificios con estos filtros\n              </p>\n              <button\n                @click=\"clearFilters()\"\n                class=\"mt-3 text-xs font-semibold text-white bg-material-dark px-3 py-2\"\n              >\n                Quitar filtros\n              </button>\n            </div>\n          </div>\n          <p class=\"px-6 py-4 text-xs text-gray-500\">\n            <i class=\"fa-solid fa-circle-info mr-1.5\" aria-hidden=\"true\"></i\n            >Administras con tu identidad de superadministrador. Los cambios\n            conservan sus registros de auditoría.\n          </p>\n        </div>\n      </section>\n\n      <section\n        x-show=\"page === 'administradores'\"\n        x-cloak\n        data-panel-page=\"administradores\"\n        id=\"administradores\"\n        class=\"bg-white p-6 shadow-soft\"\n      >\n        <h2 class=\"font-bold text-material-dark\">\n          Administradores de edificios\n        </h2>\n        <template x-for=\"b in buildings\" :key=\"b.id\"\n          ><div class=\"mt-3 border-t pt-3 flex justify-between gap-4\">\n            <div>\n              <strong x-text=\"b.name\"></strong>\n              <p class=\"text-sm\" x-text=\"b.admin\"></p>\n            </div>\n            <button @click=\"enter(b,'users')\" class=\"text-sm underline\">\n              Gestionar cuentas\n            </button>\n          </div></template\n        >\n      </section>\n      <div x-show=\"page === 'flota'\" x-cloak class=\"mb-4 text-sm\">\n        <a\n          href=\"?section=configuration\"\n          @click.prevent=\"goTo('configuration')\"\n          class=\"inline-flex items-center justify-center bg-material-dark text-white px-4 py-3 font-medium\"\n          >Administrar relés y conexión MQTT</a\n        >\n      </div>\n      <!-- FLOTA -->\n      <section\n        x-show=\"page === 'flota'\"\n        x-cloak\n        data-panel-page=\"flota\"\n        id=\"flota\"\n        class=\"grid grid-cols-1 lg:grid-cols-2 gap-6\"\n        aria-label=\"Flota de dispositivos\"\n      >\n        <div class=\"bg-white shadow-soft p-5 md:p-6\">\n          <h2 class=\"text-material-dark font-bold text-base\">\n            Versión de firmware\n          </h2>\n          <p class=\"text-xs text-gray-500 mt-1\">\n            Versiones informadas por los dispositivos consultados\n          </p>\n\n          <div\n            class=\"mt-5 flex h-6 gap-[2px]\"\n            role=\"img\"\n            :aria-label=\"firmwareLabel\"\n          >\n            <template x-for=\"f in firmware\" :key=\"f.v\">\n              <div\n                x-show=\"f.n > 0\"\n                :class=\"f.cls\"\n                :style=\"firmwareWidth(f)\"\n                :title=\"f.v + ': ' + f.n\"\n              ></div>\n            </template>\n          </div>\n          <ul class=\"mt-4 space-y-2\">\n            <template x-for=\"f in firmware\" :key=\"f.v\">\n              <li class=\"flex items-center gap-3 text-sm\">\n                <span class=\"w-2.5 h-2.5\" :class=\"f.cls\"></span>\n                <span class=\"font-mono text-material-dark\" x-text=\"f.v\"></span>\n                <span class=\"ml-auto text-gray-500\"\n                  ><span\n                    class=\"font-medium text-material-dark\"\n                    x-text=\"f.n\"\n                  ></span>\n                  dispositivos</span\n                >\n              </li>\n            </template>\n          </ul>\n\n          <p class=\"mt-6 text-xs\">\n            Inventario: hasta 500 relés. Versiones reportadas en las consultas\n            de esta sesión. Sin consultar significa que aún no hay datos. Las\n            actualizaciones se realizan desde ESPHome.\n          </p>\n        </div>\n        <div class=\"bg-white shadow-soft p-5 md:p-6\">\n          <h2 class=\"text-material-dark font-bold text-base\">\n            Comprobar dispositivos\n          </h2>\n          <p class=\"text-xs text-gray-500 mt-1\">\n            <span x-text=\"offline.length\"></span> dispositivos para comprobar\n          </p>\n          <ul class=\"mt-4 divide-y divide-material-border\">\n            <template x-for=\"d in offline\" :key=\"d.id\">\n              <li class=\"py-3 flex items-center gap-3\">\n                <div\n                  class=\"h-9 w-9 shrink-0 bg-red-50 text-red-600 flex items-center justify-center\"\n                >\n                  <i\n                    class=\"fa-solid fa-plug-circle-xmark text-sm\"\n                    aria-hidden=\"true\"\n                  ></i>\n                </div>\n                <div class=\"min-w-0 flex-1\">\n                  <p\n                    class=\"font-mono text-sm font-medium text-material-dark truncate\"\n                    x-text=\"d.id\"\n                  ></p>\n                  <p\n                    class=\"text-xs text-gray-500 truncate\"\n                    x-text=\"d.building + ' · visto ' + d.last + ' · última señal ' + d.rssi\"\n                  ></p>\n                </div>\n                <button\n                  @click=\"retry(d)\"\n                  :disabled=\"d.pinging\"\n                  class=\"shrink-0 px-2.5 py-1.5 text-xs font-semibold border border-gray-300 text-material-dark hover:bg-gray-50 disabled:opacity-60 flex items-center gap-1.5\"\n                >\n                  <i\n                    :class=\"d.pinging ? 'fa-solid fa-spinner fa-spin' : 'fa-solid fa-rotate'\"\n                    class=\"text-[10px]\"\n                    aria-hidden=\"true\"\n                  ></i\n                  ><span x-text=\"d.pinging ? 'Probando…' : 'Comprobar'\"></span>\n                </button>\n              </li>\n            </template>\n            <li\n              x-show=\"offline.length === 0\"\n              x-cloak\n              class=\"py-8 text-center text-sm text-material-text\"\n            >\n              No hay dispositivos pendientes de comprobar.\n            </li>\n          </ul>\n        </div>\n      </section>\n\n      <!-- AUDITORÍA -->\n      <section\n        x-show=\"page === 'configuration' || page === 'reports' || page === 'building' || page === 'new'\"\n        x-cloak\n      >\n        <div id=\"management-root\"></div>\n      </section>\n      <section\n        x-show=\"page === 'auditoria'\"\n        x-cloak\n        data-panel-page=\"auditoria\"\n        id=\"auditoria\"\n        class=\"\"\n        aria-labelledby=\"t-aud\"\n      >\n        <div class=\"relative bg-white shadow-soft\">\n          <div\n            class=\"px-5 md:px-6 py-4 bg-material-dark shadow-floating mx-4 -mt-6 flex justify-between items-center\"\n          >\n            <h2 id=\"t-aud\" class=\"text-white font-bold text-base\">Auditoría</h2>\n          </div>\n          <div\n            class=\"px-5 md:px-6 pt-5 flex\"\n            role=\"group\"\n            aria-label=\"Filtrar auditoría\"\n          >\n            <button\n              @click=\"auditFilter = 'todo'\"\n              :aria-pressed=\"auditFilter === 'todo'\"\n              class=\"px-3 py-2 text-xs font-medium border\"\n              :class=\"auditFilter === 'todo' ? 'bg-material-dark text-white border-material-dark' : 'border-gray-300 text-material-dark hover:bg-gray-50'\"\n            >\n              Todo\n            </button>\n            <button\n              @click=\"auditFilter = 'mine'\"\n              :aria-pressed=\"auditFilter === 'mine'\"\n              class=\"px-3 py-2 text-xs font-medium border -ml-px\"\n              :class=\"auditFilter === 'mine' ? 'bg-material-dark text-white border-material-dark' : 'border-gray-300 text-material-dark hover:bg-gray-50'\"\n            >\n              Mis acciones\n            </button>\n          </div>\n          <ul class=\"mt-3 pb-2\">\n            <template x-for=\"(a, i) in auditShown\" :key=\"i + a.action + a.ago\">\n              <li\n                class=\"flex items-center gap-4 px-5 md:px-6 py-3 border-b border-material-border last:border-0\"\n              >\n                <div\n                  class=\"h-9 w-9 shrink-0 flex items-center justify-center\"\n                  :class=\"a.icon === 'fa-user-secret' ? 'bg-amber-100 text-amber-700' : 'bg-gray-50 text-material-dark'\"\n                >\n                  <i\n                    :class=\"'fa-solid ' + a.icon\"\n                    class=\"text-sm\"\n                    aria-hidden=\"true\"\n                  ></i>\n                </div>\n                <div class=\"min-w-0 flex-1\">\n                  <p\n                    class=\"text-sm font-medium text-material-dark\"\n                    x-text=\"a.action\"\n                  ></p>\n                  <p\n                    class=\"text-xs text-gray-400 truncate\"\n                    x-text=\"a.actor\"\n                  ></p>\n                </div>\n                <p class=\"text-xs text-gray-500 shrink-0\" x-text=\"a.ago\"></p>\n              </li>\n            </template>\n          </ul>\n        </div>\n      </section>\n\n      <section\n  x-show=\"page === 'profile'\"\n  x-cloak\n  data-panel-page=\"profile\"\n  class=\"max-w-xl mx-auto w-full\"\n  x-data=\"profilePanel\"\n  x-init=\"loadProfile()\"\n>\n  <p role=\"alert\" class=\"text-sm text-red-700 mb-3\" x-text=\"profileError\"></p>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mb-4\">\n    <h2 class=\"text-xl font-bold text-material-dark\">Mi perfil</h2>\n    <p class=\"text-sm mt-2 text-material-text\">\n      Tu cuenta es la misma para todos tus edificios.\n    </p>\n    <p class=\"text-xs mt-5 text-material-text\">Teléfono</p>\n    <p class=\"font-medium break-all mt-1\" x-text=\"phone\"></p>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mb-4\">\n    <h3 class=\"font-bold\">Cambiar teléfono</h3>\n    <p class=\"text-sm my-3\">\n      Se actualizará en todos tus edificios y se cerrará tu sesión. Incluye el\n      código de país.\n    </p>\n    <form\n      @submit.prevent=\"saveProfilePhone()\"\n      x-show=\"!phoneSaved && !passwordSaved\"\n      class=\"space-y-4\"\n    >\n      <label class=\"block text-sm\"\n        >Nuevo teléfono<input\n          type=\"tel\"\n          x-model=\"newPhone\"\n          required\n          class=\"field\"\n          placeholder=\"+52 55 1234 5678\" /></label\n      ><label class=\"block text-sm\"\n        >Contraseña para cambiar teléfono<input\n          type=\"password\"\n          x-model=\"phoneSecret\"\n          required\n          autocomplete=\"current-password\"\n          class=\"field\" /></label\n      ><button\n        class=\"w-full bg-material-dark text-white px-4 py-3\"\n        :disabled=\"profileBusy\"\n      >\n        Guardar teléfono\n      </button>\n    </form>\n    <div x-show=\"phoneSaved\" role=\"status\">\n      <p>Teléfono actualizado.</p>\n      <a href=\"/login\" class=\"underline\"\n        >Iniciar sesión con el nuevo teléfono</a\n      >\n    </div>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6\">\n    <h3 class=\"font-bold text-material-dark\">Cambiar contraseña</h3>\n    <p class=\"text-sm mt-2 mb-4\">\n      Por seguridad, al guardarla tendrás que iniciar sesión de nuevo.\n    </p>\n    <form\n      @submit.prevent=\"saveProfilePassword()\"\n      x-show=\"!passwordSaved && !phoneSaved\"\n      class=\"space-y-4\"\n    >\n      <label class=\"block text-sm\"\n        >Contraseña actual<input\n          type=\"password\"\n          x-model=\"currentSecret\"\n          autocomplete=\"current-password\"\n          required\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><label class=\"block text-sm\"\n        >Nueva contraseña<input\n          type=\"password\"\n          x-model=\"secret\"\n          autocomplete=\"new-password\"\n          required\n          minlength=\"8\"\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><label class=\"block text-sm\"\n        >Repetir nueva contraseña<input\n          type=\"password\"\n          x-model=\"confirmSecret\"\n          autocomplete=\"new-password\"\n          required\n          minlength=\"8\"\n          maxlength=\"128\"\n          class=\"field\" /></label\n      ><button\n        type=\"submit\"\n        :disabled=\"profileBusy\"\n        class=\"w-full bg-material-dark text-white px-4 py-3 font-medium disabled:opacity-50\"\n      >\n        Guardar contraseña\n      </button>\n    </form>\n    <div x-show=\"passwordSaved\" role=\"status\" class=\"bg-green-50 p-4 text-sm\">\n      <p>Contraseña actualizada. Inicia sesión con tu nueva contraseña.</p>\n      <a\n        href=\"/login\"\n        class=\"inline-block mt-3 bg-material-dark text-white px-4 py-3\"\n        >Volver a iniciar sesión</a\n      >\n    </div>\n  </div>\n  <div class=\"bg-white shadow-soft p-5 md:p-6 mt-4\">\n    <h3 class=\"font-bold\">PortonSmart en tu celular</h3>\n    <p class=\"text-sm my-3\">\n      Agrega el icono a inicio para entrar más fácilmente. Necesitas internet\n      para usar los accesos.\n    </p>\n    <button\n      type=\"button\"\n      data-install-app\n      class=\"bg-material-dark text-white px-4 py-3\"\n    >\n      Instalar en mi celular\n    </button>\n  </div>\n</section>\n\n      <p class=\"mt-8 text-center text-xs text-material-text\">\n        PortonSmart · Plataforma · consultas bajo demanda\n      </p>\n    </div>\n  </main>\n\n  <div\n    x-show=\"toastOn\"\n    x-cloak\n    x-transition.opacity\n    role=\"status\"\n    aria-live=\"polite\"\n    class=\"fixed z-50 bottom-6 left-1/2 -translate-x-1/2 max-w-[92vw] bg-material-dark text-white text-sm px-4 py-3 shadow-floating flex items-center gap-2\"\n  >\n    <i class=\"fa-solid fa-circle-check text-emerald-400\" aria-hidden=\"true\"></i\n    ><span x-text=\"toastMsg\"></span>\n  </div>\n</body>\n"};
